/*SAYX_BEGIN*/const SAY_X={"유비무환": {"s": ["하준이는 축구 시합 전에 여분 축구화 끈을 가방에 챙겼어요. 시합 중에 끈이 끊어졌지만 바로 갈아 묶고 계속 뛰었어요.", "엄마는 캠핑 가기 전에 손전등 건전지를 새것으로 갈아 두셨어요. 밤에 텐트 불이 꺼졌지만 손전등 덕분에 걱정 없었어요.", "소율이는 체험 학습 전날 밤에 엄마 전화번호를 수첩에 적어 두었어요. 휴대폰이 꺼졌을 때도 선생님 전화로 바로 연락할 수 있었어요.", "예린이는 설날에 할머니 댁에 가기 전, 멀미약과 비닐봉지를 미리 챙겼어요. 차가 많이 흔들렸지만 걱정 없이 잘 갔어요.", "도서관에서 책을 빌리기 전에 민규는 대출 카드를 미리 가방에 넣어 두었어요. 덕분에 줄을 서자마자 바로 빌릴 수 있었어요."], "sim": [{"k": "거안사위(居安思危)", "m": "편안할 때도 위험을 미리 생각함"}, {"k": "돌다리도 두들겨 보고 건너라", "m": "잘 아는 일도 조심하라"}], "opp": [{"k": "소 잃고 외양간 고친다", "m": "일을 그르친 뒤에야 손씀"}, {"k": "사후약방문(死後藥方文)", "m": "때가 지난 뒤에 대책을 세움"}]}, "타산지석": {"s": ["동생이 사탕을 많이 먹고 이가 썩어 치과에 가는 것을 본 유진이는, 사탕을 먹은 뒤에 꼭 이를 닦기로 했어요.", "옆집 강아지가 목줄 없이 산책하다 길을 잃은 것을 본 태민이는, 자기 강아지와 산책할 때 꼭 목줄을 채워요.", "축구 경기에서 상대 선수가 심한 반칙으로 퇴장당하는 것을 본 시우는, 자기는 경기 규칙을 꼭 지키기로 다짐했어요.", "놀이공원에서 한 아이가 키 제한을 무시하고 타려다 직원에게 제지당하는 걸 본 하늘이는, 줄 서기 전에 꼭 안내판을 읽기로 했어요.", "도서관에서 큰 소리로 떠들다 쫓겨나는 형을 본 다은이는, 자기는 조용히 책을 읽어야겠다고 다짐했어요."], "sim": [{"k": "반면교사(反面敎師)", "m": "남의 나쁜 점을 보고 배움"}], "opp": [{"k": "전철을 밟다", "m": "앞사람의 실수를 똑같이 되풀이함"}]}, "언행일치": {"s": ["누나는 '오늘부터 매일 줄넘기 100개를 하겠다'고 말하더니, 정말 한 달 동안 하루도 빠짐없이 줄넘기를 했어요.", "삼촌은 '방학하면 놀이공원에 데려가 줄게'라고 하시더니, 정말 방학 첫 주에 우리를 놀이공원에 데려가셨어요.", "'강아지 산책은 내가 맡을게'라고 한 윤호는, 비 오는 날에도 우비를 입고 강아지와 산책을 나가요.", "'생일 파티 끝나면 정리는 내가 할게'라고 말한 서진이는, 친구들이 돌아가자 정말 혼자서 풍선과 접시를 다 치웠어요.", "'캠핑 가면 내가 설거지할게'라고 약속한 태오는, 저녁을 먹고 나서 말한 그대로 그릇을 깨끗이 씻었어요."], "sim": [], "opp": [{"k": "표리부동(表裏不同)", "m": "겉과 속이 다름"}]}, "우공이산": {"s": ["한글을 모르시던 할머니가 매일 공책에 글씨 연습을 하셔서, 2년 뒤에는 손주에게 편지를 직접 써 주셨어요.", "시우네 가족은 날마다 화단의 돌을 몇 개씩 골라냈더니, 한 달 뒤 돌밭이던 화단이 예쁜 꽃밭이 되었어요.", "물을 무서워하던 도현이가 매주 조금씩 수영 연습을 해서, 1년 뒤에는 수영장 끝까지 혼자 헤엄쳐 갔어요.", "피아노 학원에 다니는 채원이는 어려운 곡을 매일 한 줄씩 연습했어요. 석 달 뒤 발표회에서 그 곡을 끝까지 멋지게 쳤어요.", "저금통에 날마다 동전 하나씩 넣은 지후는, 일 년 뒤 모은 돈으로 사고 싶던 책 세트를 샀어요."], "sim": [{"k": "마부작침(磨斧作針)", "m": "도끼를 갈아 바늘을 만듦"}, {"k": "열 번 찍어 안 넘어가는 나무 없다", "m": "꾸준히 애쓰면 결국 이룸"}, {"k": "티끌 모아 태산", "m": "작은 것도 모이면 커짐"}], "opp": [{"k": "작심삼일(作心三日)", "m": "결심이 사흘을 못 감"}]}, "다사다난": {"s": ["이번 학기에 우리 집은 이사를 하고, 강아지가 새로 오고, 할머니가 입원도 하셨어요. 정말 많은 일이 있었어요.", "올해 축구부는 감독님이 바뀌고, 대회에서 우승도 하고, 주장이 다쳐 쉬기도 했어요. 일도 많고 걱정도 많았어요.", "캠핑 가는 날 차가 꽉 막히고, 텐트가 바람에 날아가고, 밤에는 비까지 왔어요. 그래도 별똥별을 보는 기쁜 일도 있었어요.", "이번 추석에 우리 가족은 길이 막혀 고생하고, 할아버지가 편찮으시고, 사촌 동생이 태어나는 등 정말 많은 일을 겪었어요.", "체육대회 날 갑자기 비가 오고, 계주 바통을 떨어뜨리고, 응원 도구가 망가지는 등 이런저런 일이 끊이지 않았어요."], "sim": [{"k": "우여곡절(迂餘曲折)", "m": "복잡한 사정과 변화가 많음"}, {"k": "파란만장(波瀾萬丈)", "m": "변화와 어려움이 아주 많음"}], "opp": [{"k": "무사태평(無事泰平)", "m": "아무 일 없이 편안함"}]}, "새옹지마": {"s": ["뽑기에서 꽝이 나와 아쉬워하던 서윤이는 대신 받은 작은 씨앗을 심었어요. 그 씨앗이 자라 반에서 제일 예쁜 꽃을 피웠어요.", "반 대표 계주 선수에서 떨어진 하람이는 속상했어요. 그런데 대신 응원단장을 맡아 반 친구들에게 큰 인기를 얻었어요.", "아빠 회사 일로 시골로 이사 가게 된 민호는 친구들과 헤어져 울었어요. 그런데 시골에서 강아지도 키우고 새 친구도 많이 생겼어요.", "생일 파티에 늦어 속상했던 유나는, 늦게 간 덕분에 마지막에 남은 큰 케이크 조각을 받았어요. 그런데 그걸 먹고 배탈이 났어요.", "학원 버스를 놓쳐 걸어가던 건우는 길에서 잃어버렸던 강아지를 우연히 찾았어요. 나쁜 일이 좋은 일로 바뀌었어요."], "sim": [{"k": "전화위복(轉禍爲福)", "m": "나쁜 일이 오히려 좋은 일이 됨"}], "opp": []}, "어부지리": {"s": ["두 강아지가 장난감 공을 서로 차지하려고 으르렁대는 사이, 고양이가 슬쩍 공을 물고 가 버렸어요.", "보드게임에서 두 친구가 서로만 방해하며 다투는 사이, 조용히 말을 옮긴 유나가 먼저 도착해서 이겼어요.", "시장에서 두 손님이 마지막 남은 수박을 서로 사겠다고 다투는 동안, 뒤에 온 할머니가 그 수박을 사 가셨어요.", "동생과 사촌이 마지막 송편을 서로 먹겠다고 다투는 사이에, 옆에 있던 수민이가 조용히 집어 먹었어요.", "체육대회 줄넘기 결승에서 1등과 2등 후보가 서로 부딪혀 넘어지는 바람에, 뒤에 있던 지성이가 1등을 했어요."], "sim": [{"k": "견토지쟁(犬兎之爭)", "m": "둘이 싸우다 남 좋은 일만 함"}], "opp": []}, "호사다마": {"s": ["기다리던 놀이공원에 간 날, 도착하자마자 제일 타고 싶던 놀이기구가 고장 나서 멈췄어요.", "새 강아지를 데려와 온 가족이 기뻐했는데, 다음 날 강아지가 배탈이 나서 병원에 가야 했어요.", "엄마 생신을 축하하려고 케이크를 사 왔는데, 집에 오다가 그만 케이크 상자를 떨어뜨렸어요.", "캠핑장에 도착해 멋진 경치에 신났던 소은이네 가족은, 텐트를 치자마자 갑자기 소나기가 쏟아져 흠뻑 젖었어요.", "요리 대회에서 1등을 해서 기뻐하던 민준이는, 상장을 들고 집에 가다가 그만 넘어져서 상장이 찢어졌어요."], "sim": [{"k": "좋은 일에는 마가 낀다", "m": "좋은 일에 방해가 생기기 쉬움"}], "opp": []}, "배은망덕": {"s": ["수학 문제를 친절히 가르쳐 준 짝에게, 영호는 시험이 끝나자 '너 때문에 헷갈렸잖아'라며 친구들 앞에서 흉을 봤어요.", "이사 온 첫날 동네를 안내해 준 이웃에게, 그 집 아이는 고맙다는 말은커녕 이웃집 담에 몰래 낙서를 했어요.", "이야기 속 고양이는 추운 날 자기를 데려와 돌봐 준 할머니의 생선을, 몸이 낫자마자 몽땅 훔쳐 달아났어요.", "학원에서 숙제를 다 보여 준 친구가 곤란할 때, 태민이는 '나랑 상관없어' 하며 모르는 척했어요.", "생일 파티에 초대해 주고 선물까지 챙겨 준 친구를, 하린이는 자기 생일 파티에는 일부러 부르지 않았어요."], "sim": [{"k": "은혜를 원수로 갚는다", "m": "고마운 사람에게 해를 끼침"}, {"k": "물에 빠진 사람 건져 놓으니 보따리 내놓으라 한다", "m": "도움받고도 오히려 트집 잡음"}], "opp": [{"k": "결초보은(結草報恩)", "m": "죽어서도 은혜를 갚음"}, {"k": "각골난망(刻骨難忘)", "m": "은혜를 뼈에 새겨 잊지 않음"}]}, "견문발검": {"s": ["축구를 하다가 친구가 찬 공이 살짝 발에 맞았을 뿐인데, 태호는 얼굴이 빨개지며 경기를 그만두겠다고 소리쳤어요.", "동생이 게임에서 딱 한 판 이겼다고, 누나는 게임기를 내던지고 일주일 동안 동생과 말도 안 했어요.", "강아지가 실내화를 한 번 물었다고, 형은 강아지를 다른 집에 보내 버리자며 길길이 화를 냈어요.", "급식 줄에서 친구가 국물 한 방울을 튀겼을 뿐인데, 시원이는 화를 내며 선생님께 이르겠다고 소리쳤어요.", "버스에서 옆 사람 가방이 살짝 스쳤다고, 형은 얼굴이 빨개지도록 화를 내며 따졌어요."], "sim": [{"k": "모기 보고 칼 빼기", "m": "작은 일에 크게 화냄"}], "opp": []}, "호가호위": {"s": ["삼촌이 축구 선수라는 이유로, 경민이는 운동장에서 '다 비켜, 우리 삼촌 알지?' 하며 친구들을 쫓아냈어요.", "선생님 심부름을 맡은 하윤이가 '선생님이 그러셨어!' 하며 시키지도 않은 일을 친구들에게 마음대로 시켰어요.", "덩치 큰 개를 데리고 산책하던 아이가, 개만 믿고 작은 아이들에게 '저리 가!'라며 큰소리를 쳤어요.", "사촌 형이 학원 선생님이라고, 다인이는 학원에서 '우리 형한테 말할 거야' 하며 다른 친구들에게 큰소리쳤어요.", "아빠가 놀이공원 직원이라며, 준혁이는 줄도 안 서고 '나는 먼저 타도 돼' 하고 친구들 앞에서 으스댔어요."], "sim": [{"k": "등에 업다", "m": "남의 힘을 믿고 의지함"}], "opp": []}, "우유부단": {"s": ["놀이공원에서 무엇부터 탈지 고민만 하던 지원이는, 줄이 점점 길어져 결국 하나도 못 탔어요.", "새 강아지 이름을 정해야 하는데, 은우는 '초코? 아니 콩이? 아니면 보리?' 하며 일주일째 못 정했어요.", "축구 시합에서 공을 받은 서준이가 슛할까 패스할까 망설이는 사이, 상대 선수가 공을 빼앗아 갔어요.", "생일 선물을 고르러 간 민서는 인형과 필통 사이에서 한 시간 동안 고민만 하다가, 가게 문 닫을 시간이 되어 아무것도 못 샀어요.", "도서관에서 빌릴 책을 고르던 지환이는 '이것도 좋고 저것도 좋은데…' 하다가 결국 빈손으로 나왔어요."], "sim": [{"k": "좌고우면(左顧右眄)", "m": "이리저리 살피며 망설임"}], "opp": [{"k": "일도양단(一刀兩斷)", "m": "머뭇거리지 않고 딱 잘라 결정함"}]}, "설상가상": {"s": ["자전거를 타다 넘어져 무릎이 까졌는데, 일어나 보니 자전거 바퀴까지 터져 있었어요.", "강아지가 아파서 동물 병원에 갔는데, 돌아오는 길에 자동차까지 고장 나서 멈춰 버렸어요.", "캠핑장에 도착해 보니 텐트 막대를 집에 두고 왔고, 밤에는 비까지 쏟아졌어요.", "장보러 갔다가 지갑을 두고 온 걸 알았는데, 다시 집에 가려니 비까지 쏟아졌어요. 수빈이는 울상이 되었어요.", "생일 파티 날 감기에 걸린 윤서는, 그것도 모자라 케이크까지 떨어뜨려 망가졌어요."], "sim": [{"k": "엎친 데 덮친 격", "m": "나쁜 일이 겹쳐 일어남"}, {"k": "갈수록 태산", "m": "갈수록 더 어려워짐"}, {"k": "산 넘어 산", "m": "어려움이 계속 닥침"}], "opp": [{"k": "금상첨화(錦上添花)", "m": "좋은 일에 좋은 일이 더해짐"}]}, "어불성설": {"s": ["과자를 혼자 다 먹어 놓고, 동생은 '과자가 저절로 없어졌어'라고 우겼어요.", "게임을 세 시간이나 한 형이 '눈 운동하려고 게임한 거야'라고 말했어요.", "용돈을 하루 만에 다 써 버린 누나가 '돈을 아끼려고 다 쓴 거야'라고 했어요.", "학원에 늦은 동생이 '시계가 너무 빨리 가서 늦었어요'라고 말해서 모두 어이없어했어요.", "요리하다 냄비를 태운 형이 '불이 너무 뜨거워서 그래'라고 말했어요. 불은 원래 뜨거운데 말이에요."], "sim": [{"k": "언어도단(言語道斷)", "m": "말이 안 될 만큼 어이없음"}], "opp": []}, "용두사미": {"s": ["형은 '이번 방학엔 내 방을 완전히 새로 꾸민다'며 큰소리쳤는데, 결국 포스터 한 장만 붙이고 끝냈어요.", "아빠는 화분 열 개에 꽃을 심겠다며 흙을 잔뜩 사 오셨는데, 한 개만 심고 나머지는 베란다에 그대로 있어요.", "우리 팀은 축구 경기 시작하자마자 두 골을 넣으며 신났지만, 후반에는 지쳐서 공도 제대로 못 차고 졌어요.", "체육대회 응원단은 처음에 큰 북과 깃발로 멋지게 시작했지만, 끝날 무렵엔 아무도 소리를 내지 않았어요.", "주말에 '일주일 동안 요리사가 되겠다'며 앞치마까지 산 현서는, 첫날 계란 프라이 하나만 하고 그만두었어요."], "sim": [{"k": "작심삼일(作心三日)", "m": "결심이 오래가지 못함"}, {"k": "태산명동 서일필(泰山鳴動鼠一匹)", "m": "요란하게 시작했지만 결과는 보잘것없음"}], "opp": [{"k": "유종의 미", "m": "끝까지 잘 마무리함"}, {"k": "시종일관(始終一貫)", "m": "처음부터 끝까지 한결같음"}]}, "청천벽력": {"s": ["평소처럼 저녁을 먹던 중에, 아빠가 다음 달에 외국으로 이사 가게 됐다고 갑자기 말씀하셨어요.", "어제까지 신나게 뛰어놀던 강아지가 많이 아파서 수술을 해야 한다는 말을 동물 병원에서 들었어요.", "가족 여행을 가려고 공항에 도착했는데, 여권 날짜가 지나서 비행기를 탈 수 없다는 말을 들었어요.", "즐겁게 생일 파티 준비를 하던 중, 하윤이는 가장 친한 친구가 내일 먼 나라로 떠난다는 소식을 듣고 깜짝 놀랐어요.", "놀이공원에 가는 날 아침, 갑자기 놀이공원이 큰 고장으로 문을 닫았다는 뉴스를 듣고 시우는 할 말을 잃었어요."], "sim": [{"k": "마른하늘에 날벼락", "m": "뜻밖에 당한 큰일"}, {"k": "아닌 밤중에 홍두깨", "m": "뜻밖의 일이 갑자기 생김"}], "opp": []}, "고군분투": {"s": ["학급 텃밭 당번 친구들이 모두 여행을 가서, 예린이 혼자 매일 물을 주며 채소를 지켜 냈어요.", "줄다리기에서 우리 편이 거의 다 넘어졌는데, 맨 뒤의 건우가 혼자 버티며 줄을 끝까지 놓지 않았어요.", "학급 신문 만들기에서 다른 친구들이 바빠서, 수현이가 혼자 기사 쓰기와 그림 그리기를 끝까지 해냈어요.", "명절에 친척들이 잔뜩 오셨는데 엄마가 아프셔서, 민지가 혼자 그 많은 손님 상을 차리느라 애썼어요.", "체육대회 계주에서 우리 팀이 꼴찌였는데, 마지막 주자 동하가 혼자서 힘껏 달려 세 명을 따라잡았어요."], "sim": [{"k": "악전고투(惡戰苦鬪)", "m": "어려운 상황에서 힘들게 싸움"}, {"k": "고립무원(孤立無援)", "m": "홀로 남아 도와줄 이가 없음"}], "opp": []}, "불철주야": {"s": ["택배 기사님들은 명절 전에 밤낮을 가리지 않고 쉴 틈 없이 상자를 날라 주세요.", "과학 대회를 앞둔 누나는 며칠 동안 아침 일찍부터 밤늦게까지 쉬지 않고 로봇을 만들었어요.", "빵집을 하는 삼촌은 마을 축제 기간 내내 밤에도 낮에도 쉬지 않고 빵을 구우셨어요.", "병원의 간호사 선생님들은 아픈 사람들을 위해 밤이고 낮이고 쉬지 않고 돌보셨어요.", "김장철이 되자 할머니는 며칠 동안 새벽부터 한밤중까지 쉬지 않고 배추를 절이고 양념을 버무리셨어요."], "sim": [{"k": "주야장천(晝夜長川)", "m": "밤낮으로 쉬지 않고 계속함"}, {"k": "밤낮을 가리지 않다", "m": "쉬지 않고 계속 함"}], "opp": [{"k": "무위도식(無爲徒食)", "m": "하는 일 없이 놀고먹음"}]}, "삼고초려": {"s": ["학교 밴드부는 기타를 잘 치는 6학년 언니를 모시려고, 여러 번 찾아가 정성껏 부탁했어요.", "어린이 마을 신문을 만들던 아이들은 글솜씨 좋은 할아버지 댁에 세 번이나 찾아가 기자가 되어 달라고 부탁했어요.", "게임 대회 팀을 꾸리던 형은 실력 좋은 친구를 데려오려고, 거절당해도 세 번이나 다시 찾아가 부탁했어요.", "요리 동아리 회장 은채는 요리를 잘하는 서아를 동아리에 들이려고 세 번이나 찾아가 부탁했어요. 결국 서아가 들어왔어요.", "도서관 독서 모임을 만들던 우진이는 책을 많이 읽는 친구에게 여러 번 찾아가 정성껏 부탁해서 함께하게 되었어요."], "sim": [], "opp": []}, "칠전팔기": {"s": ["연을 날리려다 열 번도 넘게 떨어뜨린 지안이는, 포기하지 않고 다시 띄워서 결국 하늘 높이 날렸어요.", "요리를 처음 배운 형은 달걀말이를 몇 번이나 찢어 먹었지만, 계속 도전해서 마침내 예쁘게 말았어요.", "게임 마지막 판을 스무 번이나 지고도 다시 도전한 동생이, 드디어 마지막 판을 깼어요.", "캠핑장에서 처음 텐트를 치던 하율이는 몇 번이나 무너졌지만 계속 다시 세워서, 결국 혼자 텐트를 완성했어요.", "학원 영어 말하기 대회에서 세 번 떨어진 지아는 포기하지 않고 연습해서, 네 번째에 드디어 상을 받았어요."], "sim": [{"k": "백절불굴(百折不屈)", "m": "수없이 꺾여도 굽히지 않음"}], "opp": [{"k": "자포자기(自暴自棄)", "m": "스스로 포기해 버림"}]}, "각주구검": {"s": ["작년 여름에 매미를 잡았던 나무라며, 동생은 한겨울에 그 나무에 가서 매미를 찾았어요.", "게임 규칙이 새로 바뀌었는데, 준기는 옛날 규칙대로만 하겠다고 고집하다가 계속 졌어요.", "요리책에 '30분 굽기'라고 쓰여 있다며, 탄 냄새가 나는데도 형은 30분이 될 때까지 오븐에서 빵을 꺼내지 않았어요.", "작년 놀이공원에서 회전목마가 입구 옆에 있었다고, 민성이는 위치가 바뀐 올해도 그 자리에서만 회전목마를 찾았어요.", "지난번 버스 정류장이 옮겨졌다는 안내가 붙어 있는데도, 할아버지 말씀만 믿은 수호는 옛 정류장에서 한 시간이나 버스를 기다렸어요."], "sim": [{"k": "수주대토(守株待兎)", "m": "융통성 없이 한 가지만 고집함"}], "opp": [{"k": "임기응변(臨機應變)", "m": "상황에 맞게 재빨리 대처함"}]}, "등하불명": {"s": ["체육복을 찾느라 온 집을 뒤졌는데, 알고 보니 내가 메고 있던 가방 안에 들어 있었어요.", "숨바꼭질에서 술래가 온 놀이터를 찾아다녔는데, 친구는 술래 바로 뒤 나무 뒤에 숨어 있었어요.", "아빠가 리모컨을 찾느라 소파 밑까지 뒤지셨는데, 리모컨은 아빠가 깔고 앉아 계셨어요.", "생일 파티 초대장을 잃어버렸다며 온 방을 뒤지던 서연이는, 초대장이 손에 든 책 사이에 끼어 있던 걸 나중에 알았어요.", "캠핑장에서 손전등을 한참 찾던 아빠는, 손전등이 자기 목에 걸려 있다는 걸 알고 웃으셨어요."], "sim": [{"k": "등잔 밑이 어둡다", "m": "가까운 것을 오히려 모름"}, {"k": "업은 아이 삼 년 찾는다", "m": "가까이 두고 엉뚱한 데서 찾음"}], "opp": []}, "목불식정": {"s": ["옛날 이야기 속 머슴은 '一' 자처럼 생긴 막대기를 날마다 들고 다니면서도, 그 글자를 읽을 줄 몰랐어요.", "글을 배우지 못한 옛날 장사꾼은 자기 가게 간판에 쓰인 쉬운 글자도 읽지 못해 손님에게 물어봐야 했어요.", "이야기 속 도령은 서당에 다닌다고 큰소리쳤지만, 사실은 '하나 일(一)' 같은 가장 쉬운 글자도 몰랐어요.", "옛날 이야기 속 장돌뱅이는 장터 간판에 쓰인 아주 쉬운 '一' 자도 읽지 못해서 엉뚱한 가게에 들어갔어요.", "이야기 속 머슴은 주인이 써 준 '대(大)' 자 쪽지를 들고도 무슨 글자인지 하나도 몰라 그냥 들고만 다녔어요."], "sim": [{"k": "낫 놓고 기역 자도 모른다", "m": "아주 쉬운 글자도 모름"}, {"k": "일자무식(一字無識)", "m": "글자를 하나도 모름"}], "opp": [{"k": "박학다식(博學多識)", "m": "배운 것과 아는 것이 많음"}]}, "우이독경": {"s": ["축구 코치님이 혼자 공을 몰지 말고 패스하라고 매번 말씀하시는데, 태우는 오늘도 혼자 공을 몰다 빼앗겼어요.", "누나가 고양이 밥은 조금씩만 주라고 여러 번 알려 줬는데, 동생은 또 밥그릇 가득 사료를 부었어요.", "아빠가 게임은 한 시간만 하라고 열 번도 넘게 말씀하셨는데, 형은 들은 척도 안 하고 계속 게임을 했어요.", "수영장 안전 요원 선생님이 뛰지 말라고 여러 번 말씀하셨지만, 민호는 들은 척도 안 하고 계속 뛰어다녔어요.", "도서관에서 사서 선생님이 조용히 하라고 몇 번이나 말씀하셔도, 준이는 알아듣지 못한 듯 계속 떠들었어요."], "sim": [{"k": "쇠귀에 경 읽기", "m": "아무리 말해도 못 알아들음"}, {"k": "마이동풍(馬耳東風)", "m": "남의 말을 흘려들음"}], "opp": [{"k": "문일지십(聞一知十)", "m": "하나를 들으면 열을 앎"}]}, "수주대토": {"s": ["어제 낚시터에서 물고기가 저절로 배 위로 뛰어올라 잡혔다고, 오늘은 낚싯대도 안 드리우고 앉아서 기다렸어요.", "작년에 마당에 토마토가 저절로 자랐다고, 동생은 올해 씨도 안 뿌리고 토마토가 열리기만 기다렸어요.", "한 번 경품에 당첨된 삼촌은 그 뒤로 일은 안 하고, 매일 응모만 하며 또 당첨되기만 기다려요.", "작년 체육대회에서 운 좋게 상을 받은 은호는, 올해는 연습도 안 하고 '또 상 받겠지' 하며 놀기만 했어요.", "놀이공원 뽑기에서 한 번 큰 인형을 뽑은 동생은, 그 뒤로 매번 뽑기 기계 앞에서만 기다리며 행운을 바랐어요."], "sim": [{"k": "감나무 밑에 누워서 홍시 떨어지기를 기다린다", "m": "노력 없이 좋은 결과만 바람"}], "opp": [{"k": "우공이산(愚公移山)", "m": "꾸준히 노력하면 이루어짐"}]}, "안하무인": {"s": ["게임을 잘하는 사촌 형이 '너희는 해도 안 돼'라며 동생들에게 게임기를 주지도 않고 비웃었어요.", "새 자전거를 산 아이가 놀이터에서 '비켜, 다 내 길이야!' 하며 어린 동생들을 밀치고 다녔어요.", "마트에서 한 아저씨가 줄 선 사람들을 무시하고 맨 앞에 끼어들더니, 오히려 큰소리를 쳤어요.", "요리 학원에서 칭찬받은 태윤이는 다른 친구들 요리를 보고 '이게 무슨 음식이야, 다 엉망이네' 하며 무시했어요.", "병원 대기실에서 한 형이 다른 사람들은 상관없다는 듯 큰 소리로 떠들고, 의자에 발을 올려놓았어요."], "sim": [{"k": "방약무인(傍若無人)", "m": "곁에 사람이 없는 듯 함부로 행동함"}, {"k": "오만불손(傲慢不遜)", "m": "잘난 체하며 버릇없음"}, {"k": "기고만장(氣高萬丈)", "m": "우쭐하여 기세가 대단함"}], "opp": [{"k": "벼는 익을수록 고개를 숙인다", "m": "훌륭할수록 겸손함"}]}, "이란투석": {"s": ["동네 작은 강아지가 덩치 큰 소에게 짖으며 덤벼들었다가, 소가 콧김 한 번 불자 깜짝 놀라 도망갔어요.", "태권도를 막 시작한 노란 띠 동생이 검은 띠 사범님께 겨루기를 하자고 덤볐어요.", "바둑을 처음 배운 수진이가 바둑 대회 우승자 할아버지께 이기겠다고 도전했다가 금방 졌어요.", "처음 체스를 배운 1학년 동생이 체스 학원 선생님께 '제가 이길게요!' 하며 도전했어요.", "작은 우산 하나로 태풍 바람을 막아 보겠다고 바닷가로 나간 은결이는 금세 우산이 뒤집혀 버렸어요."], "sim": [{"k": "계란으로 바위 치기", "m": "도저히 이길 수 없는 싸움"}, {"k": "당랑거철(螳螂拒轍)", "m": "사마귀가 수레에 맞섬"}, {"k": "하룻강아지 범 무서운 줄 모른다", "m": "철없이 강한 상대에게 덤빔"}], "opp": []}, "천하태평": {"s": ["기차 출발이 10분밖에 안 남았는데, 삼촌은 짐도 안 싸고 느긋하게 커피를 마시고 계셨어요.", "축구 경기에서 우리 팀이 지고 있는데, 수비수 한 명은 운동장 구석에서 나비를 구경하고 있었어요.", "엄마 생신 파티가 한 시간 남았는데, 아빠는 케이크도 안 사 놓고 소파에서 느긋하게 텔레비전을 보셨어요.", "버스가 곧 떠나는데도, 소풍 가방을 하나도 안 싼 동생은 느긋하게 만화를 보고 있었어요.", "강아지가 사료를 다 쏟아 거실이 난장판인데, 형은 아무렇지 않게 소파에 누워 콧노래를 불렀어요."], "sim": [{"k": "무사태평(無事泰平)", "m": "아무 걱정 없이 태평함"}, {"k": "강 건너 불구경", "m": "남의 일 보듯 관심 없음"}], "opp": [{"k": "노심초사(勞心焦思)", "m": "몹시 마음 쓰며 애태움"}, {"k": "전전긍긍(戰戰兢兢)", "m": "몹시 걱정하며 조심함"}]}, "경거망동": {"s": ["민재는 줄도 안 묶은 썰매를 타고 가파른 언덕 아래로 생각 없이 뛰어 내려가려 했어요.", "준희는 요리법도 안 읽고 프라이팬에 기름을 잔뜩 붓고 불을 세게 켜 버렸어요.", "게임에서 진 하람이가 화가 나서 생각 없이 리모컨을 바닥에 던져 버렸어요.", "도서관에서 책장에 꽂힌 책을 꺼내려던 도현이가 사다리도 없이 의자를 쌓아 올라가려고 했어요.", "버스가 아직 멈추지도 않았는데, 서연이는 내리겠다고 벌떡 일어나 문 쪽으로 뛰어갔어요."], "sim": [{"k": "앞뒤를 가리지 않다", "m": "생각 없이 마구 행동하다"}], "opp": [{"k": "심사숙고(深思熟考)", "m": "깊이 잘 생각함"}, {"k": "돌다리도 두들겨 보고 건너라", "m": "잘 아는 일도 조심해서 하라"}]}, "수수방관": {"s": ["엄마가 혼자 장 본 짐을 낑낑 나르시는데, 도윤이는 소파에 누워 쳐다보기만 했어요.", "강아지가 쓰레기통을 뒤엎어 엉망인데, 형은 치우지도 않고 구경만 했어요.", "피구 경기에서 우리 팀이 지고 있는데, 서준이는 공을 피하지도 받지도 않고 보고만 있었어요.", "명절에 온 가족이 송편을 빚는데, 사촌 형은 휴대폰만 보며 한 번도 거들지 않았어요.", "캠핑장에서 아빠가 혼자 텐트를 치느라 쩔쩔매시는데, 지안이는 의자에 앉아 바라보기만 했어요."], "sim": [{"k": "강 건너 불구경", "m": "남의 일처럼 구경만 함"}, {"k": "오불관언(吾不關焉)", "m": "나는 상관 안 한다는 태도"}, {"k": "나 몰라라 하다", "m": "모른 척하고 상관 안 하다"}], "opp": [{"k": "발 벗고 나서다", "m": "적극적으로 돕고 나서다"}]}, "일구이언": {"s": ["누나는 '이 인형 너 가져'라고 해 놓고, 다음 날 '내가 언제 준다고 했어?'라며 다시 가져갔어요.", "태오는 '오늘 게임 딱 30분만 할게요'라고 해 놓고, 나중엔 '1시간이라고 했잖아요'라고 우겼어요.", "줄넘기 시합 전에는 '지면 간식 사 줄게'라더니, 지고 나서는 '그런 말 안 했는데?' 하고 딴소리를 했어요.", "학원 친구 소율이는 '이 책 다 읽으면 빌려줄게'라고 하더니, 다 읽고 나서는 '빌려준다고 안 했어'라고 했어요.", "생일 파티 전날 '내가 풍선 사 올게'라던 건우가 당일에는 '난 케이크 산다고 했잖아'라며 말을 바꿨어요."], "sim": [{"k": "이랬다저랬다 하다", "m": "말이나 행동을 자꾸 바꾸다"}, {"k": "조변석개(朝變夕改)", "m": "계획이나 말을 자주 바꿈"}], "opp": [{"k": "남아일언중천금(男兒一言重千金)", "m": "한 번 한 말은 꼭 지킨다"}, {"k": "언행일치(言行一致)", "m": "말과 행동이 같음"}]}, "작심삼일": {"s": ["서아는 '오늘부터 간식 끊기!'라고 했는데, 사흘째 되는 날 과자 봉지를 뜯었어요.", "방학 첫날 '매일 영어 단어 10개 외우기'를 정한 은호는 사흘 뒤 단어장을 서랍에 넣어 버렸어요.", "아빠는 매일 아침 산책하겠다고 운동화를 새로 샀는데, 사흘 만에 운동화가 신발장에 들어갔어요.", "강아지 산책은 매일 내가 시키겠다던 예준이가 사흘 뒤부터는 엄마에게 목줄을 넘겼어요.", "도서관에서 '하루에 책 한 권씩 읽기'를 다짐한 나은이는 사흘 만에 빌린 책을 그대로 반납했어요."], "sim": [{"k": "용두사미(龍頭蛇尾)", "m": "시작은 거창하나 끝이 흐지부지함"}, {"k": "조변석개(朝變夕改)", "m": "결심이나 계획을 자주 바꿈"}], "opp": [{"k": "초지일관(初志一貫)", "m": "처음 마음을 끝까지 지킴"}, {"k": "우공이산(愚公移山)", "m": "꾸준히 하면 산도 옮김"}]}, "구밀복검": {"s": ["게임 속 상인은 '특별히 싸게 줄게' 하고 다정하게 웃었지만, 사실은 가짜 보물을 팔아 속이려 했어요.", "옆 반 아이는 이어달리기 전에 '우리 같이 잘하자'며 웃더니, 몰래 바통을 숨겨 두었어요.", "동화 속 늑대는 '할머니야, 문 열어 주렴' 하고 상냥하게 말했지만, 속으로는 아이들을 잡아먹으려 했어요.", "체육대회 날 옆 반 아이가 '응원할게!' 하며 웃더니, 몰래 우리 팀 신발 끈을 풀어 놓았어요.", "새로 온 학원 친구는 '너랑 제일 친해' 하고 달콤하게 말하면서, 뒤로는 내 숙제를 베껴 자기 것처럼 냈어요."], "sim": [{"k": "표리부동(表裏不同)", "m": "겉과 속이 다름"}], "opp": []}, "부화뇌동": {"s": ["반장 선거에서 친구들이 다 민지를 찍는다고 하자, 하윤이도 공약은 듣지도 않고 따라서 민지를 찍었어요.", "누나 친구가 '이 게임 재미없어'라고 하자, 해 보지도 않은 동생도 '맞아, 재미없어'라고 했어요.", "가게 앞에 사람들이 줄을 서 있으니, 무엇을 파는지도 모르고 지후도 따라서 줄을 섰어요.", "놀이공원에서 한 친구가 '저 놀이기구 무섭대'라고 하자, 타 보지도 않은 친구들이 다 안 타겠다고 따라 했어요.", "생일 파티에서 누가 '피자보다 치킨이 좋아'라고 하자, 아까 피자 먹고 싶다던 도윤이도 바로 치킨이라고 했어요."], "sim": [{"k": "남이 장에 간다고 하니 거름 지고 나선다", "m": "남을 무작정 따라 함"}, {"k": "친구 따라 강남 간다", "m": "남에게 이끌려 따라 함"}], "opp": [{"k": "화이부동(和而不同)", "m": "어울리되 무턱대고 따르지 않음"}]}, "청출어람": {"s": ["아빠에게 요리를 배운 수빈이가 만든 김치볶음밥이 아빠 것보다 맛있어서 온 가족이 놀랐어요.", "형에게 줄넘기를 배운 동생이 이제는 형보다 이단 뛰기를 더 많이 해요.", "코딩 선생님께 배운 학생이 선생님도 생각 못 한 멋진 게임을 만들어서 선생님이 칭찬하셨어요.", "엄마에게 뜨개질을 배운 하린이가 이번 명절에 엄마보다 더 예쁜 목도리를 떠서 할머니께 드렸어요.", "캠핑에서 아빠에게 불 피우는 법을 배운 준서가 이제는 아빠보다 더 빨리 모닥불을 피워요."], "sim": [{"k": "후생가외(後生可畏)", "m": "후배가 선배보다 나을 수 있음"}], "opp": []}, "형설지공": {"s": ["집에 불이 잘 안 들어오던 옛날, 한 선비는 창밖 눈빛에 책을 비추어 밤새 공부했어요.", "시골에 학원이 없던 민서 이모는 라디오 강의를 들으며 몇 년을 혼자 공부해서 선생님이 되었어요.", "신문 배달을 하며 학교에 다니던 할아버지는 쉬는 틈마다 책을 펴서 끝내 박사가 되셨어요.", "집이 좁아 공부할 책상이 없던 수호는 매일 도서관 문 닫을 때까지 꾸준히 공부해서 장학생이 되었어요.", "눈이 잘 안 보이는 할머니는 돋보기를 쓰고 밤마다 한 글자씩 연습해서 마침내 한글을 다 깨치셨어요."], "sim": [{"k": "주경야독(晝耕夜讀)", "m": "낮엔 일하고 밤엔 공부함"}, {"k": "위편삼절(韋編三絶)", "m": "책을 닳도록 열심히 읽음"}], "opp": [{"k": "무위도식(無爲徒食)", "m": "하는 일 없이 놀고먹음"}]}, "금시초문": {"s": ["아빠가 '우리 할머니가 젊을 때 수영 선수였어'라고 하셔서, 윤호는 처음 듣는 이야기에 눈이 동그래졌어요.", "짝꿍이 '너 내일 발표 순서 첫 번째야'라고 했는데, 채아는 그런 이야기를 지금 처음 들었어요.", "편의점 아저씨가 '이 과자 이제 안 나와요'라고 하셔서, 단골인 민우는 처음 듣는 말에 깜짝 놀랐어요.", "명절에 큰아빠가 '네 아빠는 어릴 때 개구쟁이였어'라고 하셔서, 서윤이는 처음 듣는 이야기에 깜짝 놀랐어요.", "학원에 갔더니 선생님이 '오늘 단원 평가 보는 날이야'라고 하셨는데, 지환이는 그 말을 그때 처음 들었어요."], "sim": [{"k": "처음 듣는 소리", "m": "전혀 몰랐던 이야기"}], "opp": [{"k": "귀에 못이 박히다", "m": "같은 말을 여러 번 들음"}]}, "반신반의": {"s": ["형이 '이 뽑기 기계는 세 번째에 꼭 인형이 나와'라고 하자, 시우는 믿어도 될지 고개를 갸웃했어요.", "동생이 '내 거북이가 내 이름을 알아들어'라고 했는데, 누나는 반은 믿고 반은 의심했어요.", "일기 예보에서 내일 눈이 온다고 했지만, 하늘이 너무 맑아서 예린이는 정말일까 싶었어요.", "캠핑장에서 삼촌이 '이 숲에 반딧불이가 산대'라고 하자, 은서는 정말일까 하며 고개를 갸웃했어요.", "병원에서 의사 선생님이 '이 주사는 하나도 안 아파'라고 하셨지만, 민준이는 믿어야 할지 말아야 할지 몰랐어요."], "sim": [{"k": "긴가민가하다", "m": "그런지 아닌지 헷갈리다"}], "opp": [{"k": "철석같이 믿다", "m": "아주 굳게 믿다"}]}, "신출귀몰": {"s": ["술래잡기에서 재윤이는 미끄럼틀 위에 있다가 어느새 그네 옆에 나타나서 술래가 정신을 못 차렸어요.", "만화 속 괴도는 경찰이 쫓아가면 사라졌다가, 엉뚱한 곳에서 다시 나타났어요.", "우리 집 햄스터는 우리 안에 있는 줄 알았는데 책상 밑에, 또 어느새 이불 속에 나타났어요.", "체육대회 피구에서 유진이는 이쪽 구석에 있나 싶으면 어느새 저쪽에 가 있어서 아무도 맞히지 못했어요.", "놀이공원에서 동생이 회전목마 앞에 있다가, 어느새 솜사탕 가게 앞에, 또 금세 사라져서 엄마가 정신이 없었어요."], "sim": [{"k": "동에 번쩍 서에 번쩍", "m": "여기저기 갑자기 나타남"}], "opp": []}, "오리무중": {"s": ["엄마가 아끼던 반지가 사라졌는데, 집 안을 다 뒤져도 어디 있는지 도무지 알 수 없었어요.", "보물찾기 쪽지를 아무리 찾아봐도 힌트가 없어서 어디부터 찾아야 할지 갈피를 못 잡았어요.", "급식실 앞 낙서를 누가 했는지 며칠이 지나도 아무 단서가 없었어요.", "캠핑장에서 아빠 차 열쇠가 사라졌는데, 텐트 안과 밖을 다 찾아봐도 어디 갔는지 도무지 알 수 없었어요.", "도서관에서 빌린 책이 없어졌는데, 언제 어디서 잃어버렸는지 하나도 기억나지 않아 갈피를 못 잡았어요."], "sim": [{"k": "갈피를 못 잡다", "m": "어떻게 할지 방향을 모르다"}], "opp": [{"k": "명명백백(明明白白)", "m": "의심할 것 없이 뚜렷함"}, {"k": "불 보듯 뻔하다", "m": "아주 분명하다"}]}, "금상첨화": {"s": ["수학 시험에서 100점을 받았는데, 엄마가 선물로 새 자전거까지 사 주셨어요.", "놀이공원에 갔는데 사람이 없어서 줄을 안 섰고, 퍼레이드까지 바로 앞에서 봤어요.", "우리 집 강아지가 새끼를 낳았는데, 마침 그날이 내 생일이라 모두 함께 축하했어요.", "명절에 할머니 댁에 갔는데 맛있는 음식도 잔뜩 먹고, 사촌들이 깜짝 선물까지 줬어요.", "도서관에서 보고 싶던 책을 빌렸는데, 그 책을 쓴 작가님의 사인회까지 열려서 사인도 받았어요."], "sim": [{"k": "겹경사", "m": "기쁜 일이 겹쳐서 생김"}], "opp": [{"k": "설상가상(雪上加霜)", "m": "나쁜 일에 나쁜 일이 더함"}, {"k": "엎친 데 덮친 격", "m": "어려운 일이 겹침"}]}, "일거양득": {"s": ["설거지를 도왔더니 엄마께 칭찬도 받고 용돈도 받았어요.", "강아지와 공원을 산책했더니 강아지도 신나고 나도 운동이 됐어요.", "안 입는 옷을 바자회에 팔았더니 방도 넓어지고 돈도 생겼어요.", "엄마와 장을 보러 가서 무거운 장바구니를 들었더니, 힘도 세지고 좋아하는 과자도 하나 얻었어요.", "학원 가는 길에 버스 대신 계단 많은 길로 걸어갔더니, 다리 운동도 되고 버스비도 아꼈어요."], "sim": [{"k": "일석이조(一石二鳥)", "m": "한 번에 두 가지 이득"}, {"k": "꿩 먹고 알 먹고", "m": "한 번에 두 가지 이득"}, {"k": "도랑 치고 가재 잡는다", "m": "한 가지 일로 두 이득"}], "opp": []}, "일사천리": {"s": ["엄마와 함께 장을 보는데 쪽지에 적힌 물건을 순서대로 척척 담아서 10분 만에 끝났어요.", "캠핑장에 도착한 가족이 각자 할 일을 나눠서 텐트를 순식간에 막힘없이 쳤어요.", "받아쓰기 시험 문제를 다현이는 한 번도 멈추지 않고 술술 써 내려갔어요.", "명절 아침, 가족들이 각자 맡은 일을 척척 해서 차례 준비가 순식간에 끝났어요.", "생일 파티 준비를 하는데 친구들이 풍선, 꾸미기, 상차림을 나눠 맡아 한 시간 만에 막힘없이 끝냈어요."], "sim": [{"k": "파죽지세(破竹之勢)", "m": "거침없이 나아가는 기세"}, {"k": "순풍에 돛 단 듯", "m": "일이 순조롭게 잘됨"}], "opp": [{"k": "지지부진(遲遲不進)", "m": "일이 잘 나아가지 않음"}]}, "전화위복": {"s": ["비 때문에 소풍이 취소되어 속상했는데, 대신 박물관에 갔다가 공룡 화석을 직접 만져 봤어요.", "키우던 화분을 깨뜨려 혼났는데, 새 화분에 옮겨 심었더니 꽃이 더 크게 피었어요.", "이사 와서 친구가 없어 외로웠는데, 그래서 들어간 미술 동아리에서 단짝을 만났어요.", "감기에 걸려 체육대회에 못 나갔는데, 대신 응원 포스터를 만들었더니 응원상을 받았어요.", "학원 버스를 놓쳐 걸어가다가, 길 잃은 강아지를 찾아 주인에게 데려다줘서 칭찬을 받고 새 친구도 생겼어요."], "sim": [{"k": "새옹지마(塞翁之馬)", "m": "좋고 나쁜 일은 바뀌기 쉬움"}, {"k": "비 온 뒤에 땅이 굳어진다", "m": "어려움 뒤에 더 단단해짐"}], "opp": []}, "사공이 많으면 배가 산으로 간다": {"s": ["김밥을 만드는데 언니, 오빠, 동생이 서로 '내 방식대로 싸야 해!' 하고 끼어들어서 김밥이 다 터져 버렸어요.", "축구 시합에서 모두가 '나한테 패스해!', '이쪽으로 가!' 하고 소리쳐서 아무도 골을 넣지 못했어요.", "반 티셔츠 색을 정하는데 저마다 다른 색을 고집해서 주문 날짜를 놓쳤어요.", "생일 파티 준비를 하는데 친구들이 저마다 '이렇게 꾸미자!' 하고 우겨서 파티 시작 때까지 장식이 하나도 안 됐어요.", "캠핑장에서 삼촌, 아빠, 큰형이 서로 자기 방법대로 텐트를 치겠다고 해서 결국 텐트가 엉망으로 무너졌어요."], "sim": [], "opp": [{"k": "백지장도 맞들면 낫다", "m": "힘을 합치면 쉬워짐"}]}, "될성부른 나무는 떡잎부터 알아본다": {"s": ["다섯 살 때부터 집에 있는 고장 난 시계를 뜯어보던 삼촌은 커서 유명한 발명가가 되었어요.", "어릴 적부터 그림책을 보면 이야기를 새로 지어내던 누나가 이번에 어린이 동화 대회에서 대상을 받았어요.", "초등학교 1학년 때부터 동네 수영장에서 가장 빨랐던 아이가 커서 수영 국가대표가 되었어요.", "어릴 때부터 반려견의 행동을 꼼꼼히 관찰해 일기를 쓰던 사촌 오빠가 커서 훌륭한 수의사가 되었어요.", "유치원 때부터 엄마 옆에서 요리를 돕고 새로운 맛을 만들던 아이가 커서 유명한 요리사가 되었어요."], "sim": [{"k": "싹수가 있다", "m": "잘될 기미가 보이다"}], "opp": [{"k": "싹수가 노랗다", "m": "잘될 가능성이 안 보이다"}]}, "산 넘어 산이다": {"s": ["캠핑장에 도착해 겨우 텐트를 쳤더니 비가 쏟아지고, 이번엔 장작까지 다 젖어 버렸어요.", "잃어버린 강아지를 겨우 찾았더니, 이번엔 강아지가 진흙투성이라 목욕부터 시켜야 했어요.", "김치찌개를 끓이려는데 김치가 모자라 마트에 갔더니, 이번엔 두부가 다 팔리고 없었어요.", "병원에서 주사를 겨우 맞았더니, 의사 선생님이 '이제 쓴 약도 일주일 먹어야 해'라고 하셨어요.", "체육대회 달리기를 겨우 끝냈더니, 바로 이어서 더 힘든 줄다리기와 이어달리기가 기다리고 있었어요."], "sim": [{"k": "갈수록 태산", "m": "갈수록 더 어려워짐"}, {"k": "설상가상(雪上加霜)", "m": "나쁜 일에 나쁜 일이 더함"}, {"k": "엎친 데 덮친 격", "m": "어려운 일이 겹침"}], "opp": [{"k": "순풍에 돛 단 듯", "m": "일이 순조롭게 잘됨"}]}, "땅 짚고 헤엄치기": {"s": ["수영 선수인 삼촌에게 동네 수영장 한 바퀴는 너무 쉬운 일이었어요.", "게임을 잘하는 오빠에게 1단계 깨기는 눈 감고도 할 만큼 쉬웠어요.", "한글을 다 아는 2학년 누나에게 '가나다' 받아쓰기는 아무것도 아니었어요.", "날마다 도서관 책 정리를 돕는 지유에게 책을 번호 순서대로 꽂는 일은 아주 쉬웠어요.", "매일 장을 보는 엄마에게 마트에서 우유와 계란 찾기는 눈 감고도 할 만큼 쉬운 일이었어요."], "sim": [{"k": "누워서 떡 먹기", "m": "아주 쉬운 일"}, {"k": "식은 죽 먹기", "m": "아주 쉬운 일"}, {"k": "손바닥 뒤집기", "m": "아주 쉬운 일"}], "opp": [{"k": "하늘의 별 따기", "m": "아주 어려운 일"}]}, "윗물이 맑아야 아랫물이 맑다": {"s": ["아빠가 집에 오면 늘 손부터 씻으시니까, 동생도 보고 따라서 손을 씻게 됐어요.", "축구부 주장이 경기에서 져도 상대 팀에게 먼저 악수를 청하니, 다른 선수들도 따라서 인사했어요.", "엄마가 휴대폰 대신 책을 읽으시자, 우리 남매도 자연스럽게 책을 펴게 됐어요.", "도서관 사서 선생님이 늘 조용히 책을 정리하시니, 도서부 아이들도 따라서 조용히 일했어요.", "명절에 큰아빠가 할머니께 먼저 공손히 인사하시니, 사촌들도 모두 보고 따라서 예의 바르게 인사했어요."], "sim": [{"k": "솔선수범(率先垂範)", "m": "먼저 나서서 모범을 보임"}], "opp": []}, "강물도 쓰면 준다": {"s": ["간식 상자가 가득하다고 동생이 하루에 몇 개씩 꺼내 먹었더니, 일주일 만에 텅 비었어요.", "통에 풀이 많다고 미술 시간마다 펑펑 짜서 썼더니, 금세 바닥이 났어요.", "게임 속 금화가 많다고 마구 썼더니, 정작 꼭 필요한 아이템을 살 돈이 없었어요.", "캠핑장에서 장작이 많다고 마구 넣어 불을 피웠더니, 밤이 되자 추운데 땔감이 하나도 없었어요.", "생일 선물로 스티커를 잔뜩 받은 소희가 아무 데나 붙였더니, 정작 친구 카드 꾸밀 스티커가 없었어요."], "sim": [{"k": "근검절약(勤儉節約)", "m": "부지런하고 아껴 씀"}], "opp": [{"k": "흥청망청", "m": "돈이나 물건을 마구 씀"}]}, "물에 빠지면 지푸라기라도 잡는다": {"s": ["준비물을 깜빡한 태민이는 급한 마음에 옆 반, 앞 반 친구들에게까지 찾아가 빌려 달라고 했어요.", "놀이공원에서 엄마를 잃어버린 지아는 급해서 눈에 보이는 아무 직원에게나 매달려 도와 달라고 했어요.", "컴퓨터가 갑자기 꺼져 숙제가 날아가자, 오빠는 될지 안 될지 모르는 방법까지 다 눌러 봤어요.", "버스에서 내릴 정류장을 지나쳐 버린 하준이는 급해서 옆자리 사람, 기사님, 아무에게나 어떻게 가냐고 물었어요.", "반려 고양이가 사라지자, 다은이는 동네 사람마다 붙잡고 묻고 전봇대마다 쪽지를 붙였어요."], "sim": [{"k": "궁여지책(窮餘之策)", "m": "막다른 처지에서 짜낸 방법"}], "opp": []}, "흐르는 물은 썩지 않는다": {"s": ["반에서 받아쓰기를 제일 잘하는 유나는 매번 100점을 받아도 날마다 새 낱말을 익혀요.", "오랫동안 빵집을 한 할머니는 지금도 새로운 빵 만드는 법을 배우러 다니세요.", "줄넘기 대회에서 상을 탄 시윤이는 '다 배웠다'고 멈추지 않고 새로운 기술을 계속 연습했어요.", "요리 대회에서 상을 받은 이모는 그 뒤에도 매주 요리 학원에 다니며 새로운 요리를 배우세요.", "도서관에서 책을 제일 많이 읽어 상을 받은 태윤이는 그 뒤에도 하루도 빠짐없이 새 책을 읽어요."], "sim": [{"k": "구르는 돌에는 이끼가 끼지 않는다", "m": "꾸준히 움직이면 뒤처지지 않음"}], "opp": []}, "달도 차면 기운다": {"s": ["한때 모두가 갖고 싶어 하던 딱지가 요즘은 서랍 속에서 먼지만 쌓이고 있어요.", "예전에 손님이 가득하던 동네 놀이공원이 지금은 사람이 거의 없어 조용해요.", "작년에 반에서 제일 인기 있던 노래를 올해는 아무도 부르지 않아요.", "한때 줄이 길던 놀이터 앞 떡볶이 가게가 요즘은 손님이 없어 문을 닫았어요.", "작년 체육대회에서 모든 경기를 이기던 청팀이 올해는 한 경기도 이기지 못했어요."], "sim": [{"k": "화무십일홍(花無十日紅)", "m": "좋은 때는 오래가지 않음"}, {"k": "권불십년(權不十年)", "m": "힘과 권세는 오래가지 못함"}], "opp": []}, "쥐구멍에도 볕 들 날 있다": {"s": ["몇 년 동안 대회에서 상 하나 못 받던 언니가 꾸준히 그림을 그리더니 드디어 금상을 받았어요.", "늘 비만 오던 장마가 끝나고, 기다리던 가족 캠핑 날에 해가 쨍쨍 났어요.", "매일 지기만 하던 동생이 형과 바둑을 두어 처음으로 이겼어요.", "매번 학원 단어 시험에서 꼴찌를 하던 재민이가 꾸준히 외우더니, 드디어 반에서 1등을 했어요.", "체육대회 달리기에서 늘 마지막으로 들어오던 수아가 올해 처음으로 1등 도장을 받았어요."], "sim": [{"k": "고진감래(苦盡甘來)", "m": "고생 끝에 좋은 일이 옴"}, {"k": "음지가 양지 된다", "m": "나쁜 처지가 좋게 바뀜"}, {"k": "고생 끝에 낙이 온다", "m": "고생하면 좋은 날이 옴"}], "opp": [{"k": "흥진비래(興盡悲來)", "m": "즐거움이 다하면 슬픔이 옴"}]}, "하늘이 무너져도 솟아날 구멍이 있다": {"s": ["놀이공원에서 지갑을 잃어버려 집에 어떻게 가나 걱정했는데, 분실물 센터에 지갑이 맡겨져 있었어요.", "수학 문제가 너무 어려워 포기하려다 교과서 예제를 다시 보니 푸는 방법이 떠올랐어요.", "비가 쏟아지는데 우산이 없어 막막했는데, 가방 구석에서 작은 비옷을 찾았어요.", "버스에 교통카드를 두고 내려 학원에 어떻게 가나 했는데, 주머니에서 비상금 천 원이 나왔어요.", "생일 파티 날 케이크가 엎어져 울상이었는데, 옆집 빵집 아저씨가 남은 케이크를 싸게 주셨어요."], "sim": [{"k": "궁하면 통한다", "m": "막히면 방법이 생김"}, {"k": "호랑이에게 물려 가도 정신만 차리면 산다", "m": "위험해도 침착하면 살 수 있음"}], "opp": [{"k": "사면초가(四面楚歌)", "m": "사방이 막혀 어쩔 수 없음"}]}, "하늘의 별 따기": {"s": ["우리 동네 인기 캠핑장은 예약을 열자마자 꽉 차서 자리를 잡기가 너무 어려웠어요.", "뽑기 기계에서 제일 큰 곰 인형을 뽑는 건 너무 어려워서, 아무도 성공한 적이 없어요.", "그 운동화는 한정판이라 가게마다 다 팔려서, 구하기가 정말 어려웠어요.", "설날 기차표를 사려고 했는데 순식간에 다 팔려서, 표를 구하기가 정말 어려웠어요.", "인기 많은 수영 강좌는 신청하자마자 마감되어서, 등록하기가 너무 어려웠어요."], "sim": [{"k": "낙타가 바늘구멍 들어가기", "m": "몹시 어려운 일"}], "opp": [{"k": "땅 짚고 헤엄치기", "m": "아주 쉬운 일"}, {"k": "식은 죽 먹기", "m": "아주 쉬운 일"}]}, "마른하늘에 날벼락": {"s": ["소풍 전날 밤, 서윤이는 갑자기 열이 나서 소풍을 못 가게 됐어요. 낮까지만 해도 멀쩡했거든요.", "공원에서 아이스크림을 먹던 하준이는 갑자기 날아온 비둘기에 놀라 아이스크림을 떨어뜨렸어요.", "즐겁게 저녁을 먹고 있었는데, 갑자기 집 수도관이 터져 거실이 물바다가 됐어요.", "설날에 세뱃돈을 받고 신나 있던 민호는 갑자기 지갑을 잃어버렸어요.", "즐겁게 캠핑을 하던 서아네 가족은 갑자기 텐트 기둥이 부러져서 깜짝 놀랐어요."], "sim": [{"k": "청천벽력(靑天霹靂)", "m": "맑은 하늘에 갑자기 치는 벼락"}, {"k": "아닌 밤중에 홍두깨", "m": "갑자기 뜻밖의 일을 당함"}], "opp": [{"k": "호박이 넝쿨째 굴러떨어졌다", "m": "뜻밖에 좋은 일이 생김"}]}, "가랑비에 옷 젖는 줄 모른다": {"s": ["도윤이는 매일 밤 자기 전에 사탕을 하나씩만 먹었는데, 몇 달 뒤 치과에서 충치가 여러 개 생겼다는 말을 들었어요.", "하루에 영어 단어를 세 개씩만 외운 지우는 1년 뒤 단어를 천 개 넘게 알게 되었어요.", "책상 위에 종이를 한 장씩 그냥 올려 두었더니, 한 달 뒤엔 책상이 종이 더미로 꽉 찼어요.", "학원 숙제를 하루에 한 장씩만 미뤘던 건우는 어느새 숙제가 한 권이나 쌓였어요.", "도서관 책 반납을 하루씩 미루던 예린이는 연체료가 꽤 많이 쌓인 걸 보고 놀랐어요."], "sim": [{"k": "티끌 모아 태산", "m": "작은 것도 모이면 크게 됨"}, {"k": "적소성대(積小成大)", "m": "작은 것이 쌓여 큰 것이 됨"}], "opp": []}, "바람 앞의 등불": {"s": ["태풍이 오자 베란다에 놓인 화분이 금방이라도 떨어질 듯 흔들렸어요.", "보드게임에서 민재의 말은 딱 한 칸만 남았는데, 상대가 주사위를 던지려 하고 있었어요.", "휴대폰 배터리가 1%밖에 안 남았는데, 엄마에게 꼭 전화를 해야 해서 서아는 조마조마했어요.", "체육대회 이어달리기에서 우리 반 마지막 주자가 넘어질 듯 비틀거려 1등을 뺏길 것 같았어요.", "놀이공원에서 엄마 손을 놓친 동생 하람이는 사람들 사이에서 길을 잃을 것 같아 아슬아슬했어요."], "sim": [{"k": "풍전등화(風前燈火)", "m": "바람 앞의 등불처럼 위태로움"}, {"k": "누란지위(累卵之危)", "m": "쌓아 놓은 알처럼 위태로움"}, {"k": "백척간두(百尺竿頭)", "m": "아주 위태롭고 어려운 처지"}], "opp": []}, "비 온 뒤에 땅이 굳어진다": {"s": ["강아지를 잃어버렸다가 겨우 찾은 뒤로, 은우네 가족은 강아지를 더 아끼고 산책도 함께 하게 됐어요.", "줄다리기에서 서로 탓하며 졌던 반 친구들이 다음 대회에선 손발이 척척 맞아 이겼어요.", "동생과 크게 싸우고 서로 사과한 뒤로, 예준이는 동생과 비밀 이야기도 나누는 사이가 됐어요.", "캠핑에서 텐트를 치다 서로 다툰 시안이와 오빠는 함께 비를 피하고 나서 더 사이좋아졌어요.", "학원에서 크게 혼난 뒤 마음을 다잡은 하율이는 전보다 훨씬 성실한 학생이 되었어요."], "sim": [{"k": "전화위복(轉禍爲福)", "m": "나쁜 일이 오히려 좋은 일이 됨"}, {"k": "고진감래(苦盡甘來)", "m": "고생 끝에 즐거움이 옴"}], "opp": []}, "가는 토끼 잡으려다 잡은 토끼 놓친다": {"s": ["뽑기에서 인형을 하나 뽑은 시우는 더 큰 인형을 뽑겠다고 그 인형을 걸고 내기하다가 결국 둘 다 잃었어요.", "퀴즈 대회에서 받은 점수를 다 걸고 마지막 문제에 도전한 유나는 틀려서 점수를 몽땅 잃었어요.", "한 손에 아이스크림을 든 동생이 과자까지 잡으려다 아이스크림을 땅에 떨어뜨렸어요.", "놀이공원에서 받은 풍선을 들고 다른 풍선까지 잡으려던 유나는 원래 풍선마저 날려 버렸어요.", "장보기에서 할인 과자를 한 봉지 고른 태오는 더 큰 봉지를 찾다가 그마저 다 팔려서 못 샀어요."], "sim": [{"k": "소탐대실(小貪大失)", "m": "작은 것을 탐하다 큰 것을 잃음"}, {"k": "과유불급(過猶不及)", "m": "지나치면 모자람만 못함"}], "opp": []}, "원숭이도 나무에서 떨어진다": {"s": ["우리 반 줄넘기 왕 태민이가 오늘 줄넘기 대회에서 첫 번째로 줄에 걸렸어요.", "피아노를 10년 친 이모가 내 생일 파티에서 생일 축하 노래를 치다가 음을 틀렸어요.", "길을 아주 잘 아는 택시 기사 삼촌이 오늘은 길을 잘못 들어 한참을 돌아갔어요.", "반에서 책을 제일 많이 읽는 소은이가 도서관 퀴즈에서 쉬운 문제를 틀렸어요.", "요리사인 삼촌이 명절에 전을 부치다가 그만 하나를 까맣게 태우셨어요."], "sim": [{"k": "천려일실(千慮一失)", "m": "지혜로운 사람도 실수할 때가 있음"}], "opp": []}, "호랑이도 제 말 하면 온다": {"s": ["'삼촌은 요즘 바쁘신가?' 하고 말하는데 바로 그때 현관 벨이 울리고 삼촌이 오셨어요.", "놀이터에서 친구들과 '하윤이 강아지 진짜 귀엽지?' 하고 이야기하는데, 하윤이가 강아지를 데리고 나타났어요.", "축구 연습 중에 '코치님 오늘 안 오시나 봐' 하는 순간, 코치님이 운동장에 들어오셨어요.", "도서관에서 '수빈이는 어디 갔지?'라고 속삭이는데 바로 수빈이가 책을 들고 나타났어요.", "명절에 '큰아버지는 언제 오시려나?' 하는 순간 초인종이 딩동 울리고 큰아버지가 들어오셨어요."], "sim": [{"k": "범도 제 말 하면 온다", "m": "남의 이야기를 하면 그 사람이 나타남"}], "opp": []}, "지렁이도 밟으면 꿈틀한다": {"s": ["얌전한 고양이 나비도 동생이 계속 귀찮게 꼬리를 만지자 결국 '야옹!' 하며 할퀴었어요.", "늘 웃기만 하던 소율이가, 친구들이 자기 그림을 계속 놀리자 '이제 그만 놀려!'라고 단호하게 말했어요.", "게임에서 늘 져 주던 사촌 동생이, 형들이 계속 반칙을 하자 '나 이제 안 해!' 하고 화를 냈어요.", "늘 순하던 반려 토끼 콩이가 동생이 자꾸 귀를 잡아당기자 발을 쿵쿵 구르며 화를 냈어요.", "학원에서 늘 참기만 하던 다은이가 친구들이 계속 지우개를 빼앗자 '그만해!' 하고 크게 소리쳤어요."], "sim": [{"k": "궁서설묘(窮鼠齧猫)", "m": "쫓긴 쥐가 고양이를 문다는 뜻"}], "opp": []}, "다람쥐 쳇바퀴 돌듯": {"s": ["수학 문제를 틀려도 오답 정리를 안 하는 건우는 매번 같은 문제를 똑같이 틀렸어요.", "할머니 댁 강아지는 매일 같은 자리만 빙빙 돌며 산책을 했어요.", "주말마다 일어나서 TV 보고, 낮잠 자고, 또 TV 보는 하루가 몇 주째 계속됐어요.", "학원에 가서 같은 문제집만 풀고 집에 와서 자는 하루가 매일 반복되자 준혁이는 지루했어요.", "캠핑을 가도 매번 똑같은 곳에서 똑같은 음식만 먹으니 시윤이는 새로운 게 없다고 느꼈어요."], "sim": [{"k": "제자리걸음", "m": "발전 없이 그대로 머묾"}], "opp": [{"k": "일취월장(日就月將)", "m": "날마다 달마다 발전함"}, {"k": "괄목상대(刮目相對)", "m": "몰라보게 실력이 늘어남"}]}, "재주는 곰이 넘고 돈은 주인이 받는다": {"s": ["동생이 열심히 그린 카드를 언니가 엄마께 드리면서, 언니만 고맙다는 말을 들었어요.", "민서가 학급 화단의 꽃에 매일 물을 줬는데, 꽃이 예쁘게 피자 반장만 선생님께 칭찬받았어요.", "강아지가 재롱을 부려 사람들이 모였는데, 간식은 주인인 오빠가 다 받았어요.", "캠핑에서 텐트는 아빠가 다 쳤는데, 칭찬은 옆에서 구경만 한 삼촌이 받았어요.", "요리 시간에 지유가 김밥을 다 말았는데, 맛있다는 칭찬은 접시에 담기만 한 친구가 받았어요."], "sim": [{"k": "죽 쑤어 개 준다", "m": "애써 한 일을 남에게 빼앗김"}], "opp": []}, "하룻강아지 범 무서운 줄 모른다": {"s": ["태권도를 일주일 배운 동생이 검은 띠 관장님께 '제가 이길 수 있어요!' 하며 겨루기를 하자고 했어요.", "게임을 처음 해 본 사촌 동생이 게임 대회 우승자인 형에게 '내가 이겨 줄게!' 하고 큰소리쳤어요.", "새끼 고양이가 자기보다 몇 배나 큰 개에게 털을 세우고 덤벼들었어요.", "수영을 처음 배운 동생 로운이가 수영 선수인 코치님께 시합하자고 큰소리쳤어요.", "요리를 한 번도 안 해 본 시후가 요리사 이모에게 '내가 더 맛있게 만들 수 있어요!'라고 했어요."], "sim": [{"k": "당랑거철(螳螂拒轍)", "m": "사마귀가 수레에 맞섬, 힘도 모르고 덤빔"}], "opp": []}, "굼벵이도 구르는 재주가 있다": {"s": ["달리기는 늘 꼴찌인 유준이가 반 장기 대회에서 1등을 했어요.", "말도 느리고 수줍음 많은 동생이 동물 이름 맞히기만큼은 가족 중에서 제일 잘했어요.", "공부엔 자신 없던 하린이가 캠핑에서 텐트를 누구보다 빨리 척척 쳤어요.", "뭐든 서툴다던 은찬이가 명절에 윷놀이만큼은 어른들을 다 이겼어요.", "공부도 운동도 자신 없던 나윤이가 반려 앵무새에게 말을 가르치는 건 누구보다 잘했어요."], "sim": [], "opp": []}, "까마귀 날자 배 떨어진다": {"s": ["수아가 거실에 들어서자마자 마침 액자가 벽에서 떨어져서, 엄마가 수아를 쳐다보셨어요.", "준서가 마트 진열대 옆을 지나가는데 마침 과자 상자가 우르르 쏟아져 직원이 준서를 의심했어요.", "내가 강아지 밥그릇 옆에 서 있을 때 마침 사료가 쏟아진 걸 본 동생이 '언니가 그랬지!' 했어요.", "도서관에서 지훈이가 책장 옆을 지나가는 순간 마침 책이 우르르 떨어져 지훈이가 오해를 받았어요.", "생일 파티에서 서진이가 식탁 옆에 서자마자 마침 컵이 저절로 넘어져 서진이가 혼날 뻔했어요."], "sim": [{"k": "오비이락(烏飛梨落)", "m": "까마귀 날자 배 떨어지듯 괜히 의심받음"}], "opp": []}, "낮말은 새가 듣고 밤말은 쥐가 듣는다": {"s": ["캠핑장 텐트 안에서 친구 이야기를 소곤소곤 했는데, 옆 텐트에 그 친구가 있었어요.", "단톡방에서 몰래 선생님 별명을 이야기했는데, 그 대화가 다른 반까지 퍼졌어요.", "엄마 생일 깜짝 선물 이야기를 방에서 몰래 했는데, 문밖에 엄마가 계셔서 다 들으셨어요.", "학원 버스 뒷자리에서 소곤소곤 친구 흉을 봤는데, 다음 날 그 친구가 다 알고 있었어요.", "도서관 구석에서 몰래 한 이야기를 옆 책장 뒤에 있던 친구가 다 들어 버렸어요."], "sim": [{"k": "벽에도 귀가 있다", "m": "몰래 한 말도 남이 들을 수 있음"}, {"k": "발 없는 말이 천 리 간다", "m": "말은 순식간에 멀리 퍼짐"}], "opp": []}, "꿩 먹고 알 먹고": {"s": ["걸어서 학교에 다녔더니 건강해지고 버스비도 아껴 용돈이 늘었어요.", "엄마와 함께 쿠키를 구웠더니 요리도 배우고 맛있는 쿠키도 실컷 먹었어요.", "강아지 산책을 매일 시켰더니 강아지도 신나고 나도 줄넘기 기록이 늘었어요.", "명절에 할머니 송편 빚기를 도운 하은이는 칭찬도 받고 맛있는 송편도 먹었어요.", "장보기에 따라간 재민이는 엄마 짐도 들어 드리고 덤으로 아이스크림도 얻었어요."], "sim": [{"k": "일석이조(一石二鳥)", "m": "돌 하나로 새 두 마리를 잡음"}, {"k": "도랑 치고 가재 잡고", "m": "한 가지 일로 두 가지 이익"}, {"k": "일거양득(一擧兩得)", "m": "한 번에 두 가지를 얻음"}], "opp": [{"k": "혹 떼러 갔다 혹 붙여 온다", "m": "이익 보려다 오히려 손해 봄"}]}, "뱁새가 황새를 따라가면 다리가 찢어진다": {"s": ["수영을 막 배운 지호가 형을 따라 깊은 물에 들어갔다가 물을 잔뜩 먹고 겁에 질렸어요.", "키 큰 언니처럼 높은 철봉에 매달리겠다던 동생이 떨어져 무릎이 까졌어요.", "6학년 형들과 똑같이 운동장 열 바퀴를 뛰겠다던 시윤이는 다섯 바퀴 만에 쓰러질 듯 지쳤어요.", "놀이공원에서 언니를 따라 무서운 롤러코스터를 탄 동생 아린이는 내려서 한참 울었어요.", "캠핑에서 아빠처럼 큰 장작을 혼자 나르겠다던 이준이는 결국 허리가 아파 주저앉았어요."], "sim": [{"k": "오르지 못할 나무는 쳐다보지도 마라", "m": "힘에 넘치는 일은 바라지 마라"}, {"k": "과유불급(過猶不及)", "m": "지나치면 모자람만 못함"}], "opp": []}, "가재는 게 편": {"s": ["강아지를 키우는 친구들은 모두 '강아지가 고양이보다 좋아!' 하며 강아지 키우는 친구 편을 들었어요.", "할머니와 엄마가 이야기를 나누시는데, 이모는 언제나 자기 언니인 엄마 편을 드셨어요.", "피구 경기에서 심판을 본 친구가 자기 팀에게만 유리하게 판정을 했어요.", "체육대회 줄다리기에서 다툼이 나자 같은 학원 다니는 친구들은 모두 은호 편만 들었어요.", "생일 파티에서 사촌끼리 말다툼하자 고양이를 키우는 아이들은 모두 고양이 키우는 친구 편을 들었어요."], "sim": [{"k": "초록은 동색(草綠同色)", "m": "처지가 같은 사람끼리 한편이 됨"}, {"k": "유유상종(類類相從)", "m": "비슷한 사람끼리 어울림"}], "opp": []}, "개구리 올챙이 적 생각 못 한다": {"s": ["얼마 전 줄넘기 2단 뛰기를 겨우 성공한 누나가, 이제 막 배우는 동생에게 '그것도 못 해?'라며 핀잔을 줬어요.", "작년까지 젓가락질을 못 하던 사촌 형이, 숟가락으로 먹는 동생을 '아기'라고 놀렸어요.", "처음 전학 와서 친구가 없어 외로웠던 지민이가, 새로 온 전학생을 모른 척하고 끼워 주지 않았어요.", "작년까지 혼자 버스를 못 타던 형이 이제 버스를 처음 타는 동생에게 '그것도 몰라?'라며 놀렸어요.", "얼마 전까지 라면도 못 끓이던 누나가 요리를 배우더니, 계란을 깨뜨린 동생에게 큰소리를 쳤어요."], "sim": [{"k": "초심을 잃다", "m": "처음의 마음을 잊어버림"}], "opp": []}, "고래 싸움에 새우 등 터진다": {"s": ["엄마와 아빠가 여행지를 두고 말다툼하시는 바람에, 여행 계획이 취소돼 아이들만 속상했어요.", "두 반 대표가 체육관을 서로 쓰겠다고 싸우는 사이, 기다리던 동생 반은 체육 시간을 놓쳤어요.", "큰 고양이 두 마리가 다투다가 옆에서 밥을 먹던 아기 고양이의 밥그릇이 엎어졌어요.", "명절에 삼촌 두 분이 윷놀이 규칙으로 다투시는 바람에 옆에 있던 수호는 윷놀이를 못 했어요.", "학원 선생님 두 분이 교실을 두고 다투시는 사이, 그 교실에서 공부하던 하진이네 반은 복도로 쫓겨났어요."], "sim": [], "opp": [{"k": "어부지리(漁夫之利)", "m": "둘이 싸우는 사이 남이 이익을 봄"}]}, "그물에 걸린 고기 신세": {"s": ["숨바꼭질에서 장롱 속에 숨은 서준이는 술래가 장롱 문 앞에 서자 꼼짝도 못 했어요.", "장기에서 내 왕이 사방으로 막혀서 더 이상 피할 곳이 없었어요.", "몰래 게임을 하던 오빠는 방문을 열고 들어온 아빠에게 딱 들켜 아무 변명도 못 했어요.", "놀이공원 미로에서 막다른 길에 다다른 윤재는 따라오던 형에게 꼼짝없이 잡혔어요.", "몰래 반려견 간식을 먹던 동생은 문 앞에 서 있는 아빠와 딱 마주쳐 도망갈 곳이 없었어요."], "sim": [{"k": "독 안에 든 쥐", "m": "빠져나갈 수 없는 처지"}, {"k": "진퇴양난(進退兩難)", "m": "나아가지도 물러서지도 못함"}], "opp": [{"k": "물 만난 고기", "m": "자유롭게 마음껏 활약함"}]}, "닭 쫓던 개 지붕 쳐다보듯": {"s": ["한참 줄을 서서 기다렸는데 바로 내 앞에서 놀이 기구 운행이 끝나, 우리는 멍하니 기구만 바라봤어요.", "강아지가 열심히 쫓던 고양이가 담장 위로 훌쩍 올라가 버려서, 강아지는 담장만 올려다봤어요.", "응모하려고 사이트에 들어갔는데 1초 차이로 마감돼서, 하은이는 화면만 멍하니 쳐다봤어요.", "놀이공원에서 한 시간이나 줄을 섰는데 내 차례 직전에 놀이기구가 멈춰서 민준이는 멍하니 바라보기만 했어요.", "장보기에서 마지막 남은 딸기를 집으려는 순간 다른 사람이 먼저 가져가서 라희는 허탈하게 쳐다보았어요."], "sim": [{"k": "헛물을 켜다", "m": "애쓴 일이 헛일이 됨"}], "opp": []}, "고양이 목에 방울 달기": {"s": ["가족들이 '아빠한테 게임 시간 늘려 달라고 하자!' 하고 말만 하고, 막상 아무도 말을 꺼내지 못했어요.", "친구들이 '반장에게 규칙을 바꾸자고 말하자'고 다 같이 정했지만, 누가 말할지 정하지 못해 그대로였어요.", "동생들이 '할머니께 잔소리 그만해 달라고 하자'고 했지만, 아무도 할머니 앞에 나서지 못했어요.", "학원 친구들이 '선생님께 숙제를 줄여 달라고 하자'고 했지만, 막상 말하러 가겠다는 사람은 아무도 없었어요.", "캠핑장에서 '옆 텐트에 조용히 해 달라고 말하자'고 다들 말했지만 누가 갈지는 정하지 못했어요."], "sim": [{"k": "탁상공론(卓上空論)", "m": "실천할 수 없는 헛된 의논"}, {"k": "묘두현령(猫頭懸鈴)", "m": "고양이 목에 방울 달기"}], "opp": []}, "똥 묻은 개가 겨 묻은 개 나무란다": {"s": ["편식이 아주 심한 오빠가, 당근 하나 남긴 동생에게 '골고루 먹어야지!'라고 했어요.", "수업 시간에 매일 떠드는 친구가, 한 번 속삭인 짝에게 '조용히 좀 해!'라고 했어요.", "게임을 몇 시간씩 하는 삼촌이, 10분 게임한 조카에게 '게임 너무 많이 한다'고 하셨어요.", "도서관 책을 매번 늦게 내는 형이, 하루 늦게 반납한 동생에게 '책임감이 없다'고 잔소리했어요.", "생일 파티에서 케이크를 마구 흘리며 먹던 오빠가, 부스러기 하나 흘린 동생에게 '지저분하다'고 했어요."], "sim": [{"k": "숯이 검정 나무란다", "m": "제 흉은 모르고 남을 흉봄"}, {"k": "가랑잎이 솔잎더러 바스락거린다고 한다", "m": "더 큰 허물을 가진 이가 남을 탓함"}], "opp": []}, "소 잃고 외양간 고친다": {"s": ["강아지가 문밖으로 뛰쳐나가 한참 찾은 뒤에야 현관에 안전문을 달았어요.", "휴대폰 사진이 다 지워지고 나서야 사진을 저장해 두는 방법을 배웠어요.", "비에 흠뻑 젖고 집에 와서야 가방에 우산을 넣어 두었어요.", "반려 햄스터가 우리 밖으로 나가 사라진 뒤에야 지성이는 우리 문을 꼭 잠갔어요.", "캠핑장에서 모기에 잔뜩 물리고 나서야 다인이는 모기 기피제를 챙겼어요."], "sim": [{"k": "망양보뢰(亡羊補牢)", "m": "양 잃고 우리 고친다"}, {"k": "사후약방문(死後藥方文)", "m": "때가 지난 뒤에 대책을 세움"}], "opp": [{"k": "유비무환(有備無患)", "m": "미리 준비하면 걱정이 없음"}, {"k": "돌다리도 두들겨 보고 건너라", "m": "잘 아는 일도 조심해서 하라"}]}, "가는 날이 장날": {"s": ["큰맘 먹고 유명한 떡볶이집에 갔는데, 하필 그날 가게 사장님이 휴가를 가셔서 문을 닫았어요.", "수영장에 놀러 갔더니 마침 그날 물 청소를 하는 날이라 수영을 못 했어요.", "동물원에 갔는데 마침 그날 아기 판다가 처음으로 사람들 앞에 나오는 날이라 운 좋게 볼 수 있었어요.", "생일 파티에 가려고 케이크 가게에 갔는데 하필 그날 가게가 문을 닫아서 채원이는 당황했어요.", "병원에 진료받으러 갔더니 마침 그날 의사 선생님이 휴가여서 승우는 그냥 돌아왔어요."], "sim": [{"k": "오는 날이 장날", "m": "뜻하지 않은 일과 우연히 마주침"}], "opp": []}, "떡 본 김에 제사 지낸다": {"s": ["할머니 댁에 간 김에 미뤄 두었던 할머니 휴대폰 사진 정리까지 해 드렸어요.", "이모가 사진기를 가져오신 김에, 미뤄 둔 가족사진까지 다 같이 찍었어요.", "빵을 굽느라 오븐을 켠 김에, 엄마는 고구마까지 넣어 함께 구우셨어요.", "명절에 친척들이 다 모인 김에 할아버지는 미뤄 두었던 가족 회의까지 하셨어요.", "병원에 감기 진료를 받으러 간 김에 서하는 미뤄 둔 예방 주사까지 맞았어요."], "sim": [{"k": "소매 긴 김에 춤춘다", "m": "좋은 기회에 하려던 일을 함"}, {"k": "엎어진 김에 쉬어 간다", "m": "생긴 기회에 하려던 일을 함"}], "opp": []}, "불난 집에 부채질한다": {"s": ["강아지를 잃어버려 우는 친구에게 '그러게 잘 보지 그랬어'라고 말해서 친구가 더 크게 울었어요.", "달리기에서 넘어져 속상한 동생 앞에서 오빠가 '나는 1등 했지롱!' 하며 메달을 흔들었어요.", "화가 난 아빠 옆에서 형이 '동생이 아까 또 거짓말했어요'라고 일러서 아빠가 더 화나셨어요.", "캠핑에서 텐트가 무너져 속상한 아빠 옆에서 동생 도하가 '내가 그럴 줄 알았어!' 하며 웃었어요.", "생일 파티 케이크를 떨어뜨려 우는 친구에게 지온이가 '이제 케이크 못 먹겠다~' 하고 놀렸어요."], "sim": [{"k": "불에 기름을 붓다", "m": "상황이나 화를 더 키움"}], "opp": []}, "공든 탑이 무너지랴": {"s": ["매일 아침 줄넘기를 연습한 지안이는 학교 줄넘기 대회에서 드디어 상을 받았어요.", "한 학기 동안 꾸준히 일기를 쓴 도현이는 글쓰기 대회에서 칭찬을 받았어요.", "몇 주 동안 정성껏 블록으로 만든 성이 전시회에서 많은 사람의 박수를 받았어요.", "체육대회를 위해 매일 달리기를 연습한 서율이는 이어달리기에서 멋지게 1등을 했어요.", "매일 반려견에게 앉기를 정성껏 가르친 하겸이네 강아지는 드디어 '앉아!'를 척척 해냈어요."], "sim": [{"k": "지성이면 감천", "m": "정성을 다하면 하늘도 도움"}, {"k": "우공이산(愚公移山)", "m": "꾸준히 하면 결국 해냄"}], "opp": [{"k": "사상누각(沙上樓閣)", "m": "기초가 약해 쉽게 무너짐"}]}};/*SAYX_END*/
for(const x of [...SAJA,...SOK]){ const e=SAY_X[x.k]; if(!e) continue; if(e.s&&e.s.length) x.s=x.s.concat(e.s); x.sim=e.sim||[]; x.opp=e.opp||[] }
function sayRelFind(k){ const b=String(k).replace(/\(.*?\)/g,"").replace(/\s+/g,""); return [...SAJA,...SOK].find(x=>x.k.replace(/\s+/g,"")===b) }
function sayRelHtml(x,small){ const sim=x.sim||[], opp=x.opp||[]; if(!sim.length&&!opp.length) return "";
  const chip=(r,cls)=>{ const f=sayRelFind(r.k); return `<span class="srChip ${cls} ${f?"in":""}" ${f?`data-srh="${esc(f.h)}"`:""}><b>${esc(r.k)}</b>${small?"":`<small>${esc(r.m)}</small>`}</span>` };
  return `<div class="sayRel">${sim.length?`<div class="srRow"><span class="srLab sim">🤝 비슷한 말</span>${sim.map(r=>chip(r,"sim")).join("")}</div>`:""}${opp.length?`<div class="srRow"><span class="srLab opp">↔ 반대 말</span>${opp.map(r=>chip(r,"opp")).join("")}</div>`:""}</div>` }
function bindSayRel(root){ (root||document).querySelectorAll("[data-srh]").forEach(b=>b.onclick=e=>{ e.stopPropagation(); const f=sayFind(b.dataset.srh); if(f&&(P.seen||{})[f.h]) sayDetail(f); else toast("우리가 배우는 말이에요! 학습하기에서 만나 봐요") }) }

/* ===================== 사자성어 · 속담 공부 ===================== */
const SAY_ALL={S:SAJA,P:SOK}, SAY_NAME={S:"사자성어",P:"속담"}, SAY_JO={S:"는",P:"은"};
const SAY_MASTER=4, SAY_CTX=3;   // 4번 맞히고, 그중 생활 문제(상황·빈칸·O/X)를 3번 이상 맞히면 '익힌 말' (2026-10-27)
const SAY_REVIEW_DAYS=7;     // 외운 주차는 7일마다 복습할 때가 돼요
const SAY_MILE=[[3,"말 씨앗",150],[6,"말 새싹",250],[9,"지혜 나무",350],[12,"지혜 탐험가",450],[15,"말 박사",550],[18,"지혜의 달인",650],[21,"지혜의 용사",800]];
function sayFind(h){ return SAJA.find(x=>x.h===h)||SOK.find(x=>x.h===h) }
function saySel(cat){ const k=cat==="S"?"selS":"selP"; P.set[k]=(P.set[k]||[1]).filter(w=>w>=1&&w<=SAY_WEEKS[cat]); return P.set[k] }
function sayItems(cat,weeks){ return SAY_ALL[cat].filter(x=>weeks.includes(x.w)) }
function sayMastered(x){ return ((P.mastery||{})[x.h]||0)>=SAY_MASTER && ((P.sctx||{})[x.h]||0)>=SAY_CTX }
function sayWeekDone(cat,w){ const L=SAY_ALL[cat].filter(x=>x.w===w); return L.length>0&&L.every(sayMastered) }
function sayDoneCount(cat){ let n=0; for(let w=1;w<=SAY_WEEKS[cat];w++) if(sayWeekDone(cat,w)) n++; return n }
function sayDoneWeeks(){ return sayDoneCount("S")+sayDoneCount("P") }
function sayMul(){ return Math.round((1+.05*sayDoneWeeks())*100)/100 }   // 외운 주차 1개마다 공부 코인 +5%
function sayRevDue(cat,w){ const t=(P.srev||{})[cat+w]; return sayWeekDone(cat,w)&&!!t&&Date.now()-t>SAY_REVIEW_DAYS*864e5 }
function sayStamp(){ P.srev=P.srev||{}; for(const cat of ["S","P"]) for(let w=1;w<=SAY_WEEKS[cat];w++) if(sayWeekDone(cat,w)&&!P.srev[cat+w]) P.srev[cat+w]=Date.now() }
function sayCtx(c){ if(!c||!c.cat) return; P.sctx=P.sctx||{}; P.sctx[c.h]=(P.sctx[c.h]||0)+1 }
function sayTitle(){ let t=""; for(const [n,name] of SAY_MILE) if((P.smile||0)>=n) t=name; return t }
/* 외운 주차 이정표 보상: 3·6·9…주차를 넘을 때마다 코인 상자 + 칭호 */
function sayCheckMile(){ if(!P) return; sayStamp(); const n=sayDoneWeeks(), got=SAY_MILE.filter(([k])=>k>(P.smile||0)&&k<=n);
  if(!got.length){ saveP(); return }
  P.smile=got[got.length-1][0]; const coins=got.reduce((a,m)=>a+m[2],0); P.coins+=coins; P.earned+=coins; saveP();
  const last=got[got.length-1];
  modal.dataset.dismiss="no";
  openModal(`<div class="eyebrow">WISDOM</div><h3>외운 주차 ${n}개 돌파!</h3><p>사자성어·속담을 ${n}주차나 외웠어요. 정말 대단해요!</p>
    <div class="sayBadge">${esc(last[1])}</div><p class="muted">새 칭호를 받았어요. 내 이름 옆에 표시돼요.</p>
    <div class="mc">${ico("coin","ci")}+${coins}</div><button class="btn gold big" id="smOk">보상 받기</button>`);
  setTimeout(()=>stamp("지혜<br>상자!"),200); sfx("win");
  document.getElementById("smOk").onclick=()=>{ modal.dataset.dismiss=""; closeModal(); sfx("coin"); if(document.getElementById("coinN")) countUp(P.coins-coins,P.coins) } }
/* 게임 안 문제에 섞을 말: 고른 주차에서 한 번 이상 공부한 말 */
function sayGamePool(){ if(!P) return []; const out=[]; for(const cat of ["S","P"]){ const sel=P.set[cat==="S"?"selS":"selP"]||[]; for(const x of SAY_ALL[cat]) if(sel.includes(x.w)&&(P.seen||{})[x.h]) out.push(x) } return out }

/* ----- 문제 만들기 ----- */
function sayOthers(c,n){ const L=SAY_ALL[c.cat].filter(x=>x!==c&&!(c.g&&x.g===c.g));
  const near=shuffle(L.filter(x=>Math.abs(x.w-c.w)<=2)), far=shuffle(L.filter(x=>Math.abs(x.w-c.w)>2)), out=[];
  for(const x of [...near.slice(0,2),...far,...near.slice(2)]){ if(out.length>=n) break; if(!out.some(o=>o.g&&o.g===x.g)) out.push(x) }
  for(const x of shuffle(L)){ if(out.length>=n) break; if(!out.includes(x)) out.push(x) } return out }
function makeSayQ(c,opt){ opt=opt||{}; const nm=SAY_NAME[c.cat], jo=SAY_JO[c.cat];
  let types=opt.types||(opt.short?(c.cat==="P"?["mean","cut","sit"]:["mean","sit"]):["mean","sit","sit","blank","ox",...(c.cat==="P"?["cut","cut"]:["m2"])]);
  const t=types[Math.random()*types.length|0], words=()=>shuffle([c,...sayOthers(c,3)]).map(o=>({text:o.k,ok:o===c})), base={c,why:c.t,ans:c.k};
  let q;
  if(t==="sit") q={...base,tag:"생활 속 상황",ctx:1,desc:c.s[Math.random()*c.s.length|0],q:`이 상황에 어울리는 ${nm}${jo}?`,opts:words()};
  else if(t==="blank") q={...base,tag:"대화 빈칸",ctx:1,desc:c.b,q:"빈칸에 알맞은 말은?",opts:words()};
  else if(t==="ox"){ const right=Math.random()<.5, sen=right?c.o:c.x[0]; q={...base,tag:"바르게 썼을까?",ctx:1,desc:sen,q:`'${c.k}'${c.cat==="S"?"를":"을"} 바르게 썼을까요?`,two:1,
      opts:[{text:"⭕ 바르게 썼어요",ok:right},{text:"❌ 잘못 썼어요",ok:!right}],why:right?c.t:c.x[1]} }
  else if(t==="cut"){ const others=shuffle(SOK.filter(x=>x!==c&&!(c.g&&x.g===c.g))).slice(0,3); q={...base,tag:"이어 말하기",desc:`"${c.cut[0]} ______"`,q:"빈칸에 이어질 말은?",opts:shuffle([c,...others]).map(o=>({text:o.cut[1],ok:o===c}))} }
  else if(t==="m2"){ const ot=sayOthers(c,3); q={...base,tag:"말 보고 뜻 고르기",big:c.k,desc:"",q:`'${c.k}'의 뜻은?`,long:1,opts:shuffle([c,...ot]).map(o=>({text:o.m.replace(/^.*뜻으로, /,""),ok:o===c}))} }
  else q={...base,tag:"뜻 보고 맞히기",desc:c.m,q:`이런 뜻의 ${nm}${jo}?`,opts:words()};
  if(opt.short){ q.q=q.desc?`${q.desc}  ▶ ${q.q}`:q.q; q.big=null; q.long=1 }
  return q }

/* ----- 학습하기 화면: 한자 / 사자성어 / 속담 탭 ----- */
function learnTabs(cur){ return `<div class="ltabs">${[["H","한자"],["S","사자성어"],["P","속담"]].map(([k,n])=>`<button class="ltab ${cur===k?"on":""}" data-tab="${k}">${n}${k!=="H"?`<small>${sayDoneCount(k)}/${SAY_WEEKS[k]}주</small>`:""}</button>`).join("")}</div>` }
function bindTabs(){ $app.querySelectorAll(".ltab").forEach(b=>b.onclick=()=>{ P.set.tab=b.dataset.tab; saveP(); learn() }) }
function sayLearn(cat){ const sel=saySel(cat), L=sayItems(cat,sel), d=day(), full=d.sets>=DAILY_SETS, nm=SAY_NAME[cat], done=sayDoneWeeks(), next=SAY_MILE.find(([k])=>k>done);
  const due=[]; for(let w=1;w<=SAY_WEEKS[cat];w++) if(sayRevDue(cat,w)) due.push(w);
  const wrong=(P.swrong||[]).map(sayFind).filter(x=>x&&x.cat===cat);
  $app.innerHTML = topbar("학습하기") + learnTabs(cat) + `
  <section class="panel">
    <div class="row"><h2>${nm} 몇 주차를 공부할까요?</h2><div class="row" style="gap:8px"><button class="chip" id="selNone">모두 해제</button><button class="chip" id="selAll">전체 선택</button></div></div>
    <div class="weeks">${Array.from({length:SAY_WEEKS[cat]},(_,i)=>i+1).map(w=>{ const ok=sayWeekDone(cat,w), rv=sayRevDue(cat,w), its=SAY_ALL[cat].filter(x=>x.w===w), m=its.filter(sayMastered).length;
      return `<button class="wk ${ok?"sayok":""}" data-w="${w}" aria-pressed="${sel.includes(w)}"><span>${w}</span><small>주차</small>${ok?`<span class="done" title="외운 주차">★</span>`:`<span class="sayp">${m}/${its.length}</span>`}${rv?`<span class="sayrv">복습</span>`:""}</button>` }).join("")}</div>
    <div class="row"><span class="meta">${sel.length?`${sel.length}개 주차 · ${nm} ${L.length}개 · <b style="color:var(--gold);font-weight:400">코인 ×${sayMul()}</b>`:"주차를 하나 이상 눌러 주세요"}</span>
      <span class="meta">외운 주차 <b style="color:var(--gold);font-weight:400">${done}</b>${next?` · ${next[0]}주차를 외우면 <b style="color:var(--gold);font-weight:400">'${next[1]}'</b> 칭호와 보상 상자`:" · 모든 주차를 외웠어요!"}</span></div>
    <div class="sayInfo">💡 말 하나를 <b>4번</b> 맞히고, 그중 <b>생활 문제</b>(상황·빈칸·O/X)를 <b>3번</b> 맞히면 익힌 말이 돼요. 4개를 다 익히면 그 주차에 ★! 외운 주차가 늘수록 공부 코인이 커져요 (주차마다 +5%).</div>
  </section>
  <div class="row"><h2>무엇을 할까요?</h2><span class="meta">${full?"오늘 코인 보상 세트를 모두 받았어요. 공부는 계속할 수 있어요!":`코인 받는 세트 ${d.sets}/${DAILY_SETS} · ${stairHtml(d.sets)}`}</span></div>
  <div class="acts">
    <button class="act" data-a="cards" ${L.length?"":"disabled"}><span class="ai r">${ico("cards")}</span><span><strong>카드로 익히기</strong><small>뜻과 생활 예시를 보고 뒤집어서 ${nm} 확인하기</small></span></button>
    <button class="act" data-a="mean" ${L.length?"":"disabled"}><span class="ai y">${ico("quiz")}</span><span><strong>뜻 보고 맞히기</strong><small>뜻을 읽고 알맞은 ${nm} 고르기${cat==="P"?" · 이어 말하기":""}</small><span class="rw">${ico("coin","ci")}연속 정답일수록 더 많이</span></span></button>
    <button class="act memoAct" data-a="life" ${L.length?"":"disabled"}><span class="ai mm">${ico("star")}</span><span><strong>생활 속 ${nm} <em class="memoStar">★ 실력 쑥쑥</em></strong><small>상황·대화 빈칸·바르게 썼을까? 문제로 진짜 써 보기</small><span class="rw">${ico("coin","ci")}익힌 말이 되려면 꼭 필요해요</span></span></button>
    <button class="act" data-a="mix" ${L.length?"":"disabled"}><span class="ai g">${ico("match")}</span><span><strong>섞어서 도전</strong><small>모든 문제 유형이 골고루 나와요</small></span></button>
    ${due.length?`<button class="act" data-a="review"><span class="ai b">${ico("book")}</span><span><strong>복습하기 · ${due.join(", ")}주차</strong><small>외운 지 ${SAY_REVIEW_DAYS}일이 지났어요. 다 맞히면 ★이 반짝이고 코인 ×1.3!</small></span></button>`:""}
    ${wrong.length?`<button class="act" data-a="wrong"><span class="ai r">${ico("note")}</span><span><strong>틀린 ${nm} 다시 풀기</strong><small>${wrong.length}개 · 맞히면 목록에서 지워져요</small></span></button>`:""}
  </div>`;
  bindBack(); bindTabs();
  const k=cat==="S"?"selS":"selP";
  $app.querySelectorAll(".wk").forEach(b=>b.onclick=()=>{ const w=+b.dataset.w; P.set[k]=sel.includes(w)?sel.filter(x=>x!==w):[...sel,w]; saveP(); sfx("tap"); learn() });
  document.getElementById("selAll").onclick=()=>{ P.set[k]=Array.from({length:SAY_WEEKS[cat]},(_,i)=>i+1); saveP(); learn() };
  document.getElementById("selNone").onclick=()=>{ P.set[k]=[]; saveP(); learn() };
  const T={mean:cat==="P"?["mean","mean","cut","m2"]:["mean","mean","m2"], life:["sit","sit","blank","ox"], mix:null};
  $app.querySelectorAll(".act").forEach(b=>b.onclick=()=>{ sfx("tap"); const a=b.dataset.a;
    if(a==="cards") return sayCards(L,cat);
    if(a==="review") return sayQuiz(sayItems(cat,due),cat,{review:due,types:null});
    if(a==="wrong") return sayQuiz(wrong,cat,{fromNotes:true});
    sayQuiz(L,cat,{types:T[a]}) });
  setTimeout(sayCheckMile,300) }

/* ----- 카드 ----- */
function sayCards(list,cat){ let order=shuffle(list), i=0, flip=false;
  function draw(){ const c=order[i]; markSeen(c.h); const ex=c.s[Math.random()*c.s.length|0];
    $app.innerHTML = topbar(`학습 · ${SAY_NAME[cat]} 카드`) + `
    <div class="prog"><div class="pt"><span>카드를 눌러 뒤집어요</span><b>${i+1} / ${order.length}</b></div><div class="bar"><i style="width:${(i+1)/order.length*100}%"></i></div></div>
    <button class="sayCard ${flip?"back":""}" id="sc">${flip?`<div class="scWord">${esc(c.k)}</div>${c.hz?`<div class="scHz">${esc(c.hz)}</div>`:""}
        <div class="scTip">${esc(c.t)}</div><div class="scEx"><b>이렇게 써요</b>${esc(c.o)}</div>${sayRelHtml(c)}`
      :`<div class="scLab">뜻</div><div class="scMean">${esc(c.m)}</div><div class="scLab">이런 상황에서</div><div class="scSit">${esc(ex)}</div><div class="scQ">어떤 ${SAY_NAME[cat]}일까요? 눌러서 확인!</div>`}</button>
    <div class="btns"><button class="btn ghost" id="pv" ${i?"":"disabled"}>← 이전</button><button class="btn gold" id="nx">${i<order.length-1?"다음 →":"다 봤어요!"}</button></div>`;
    bindBack();
    bindSayRel($app);
    document.getElementById("sc").onclick=()=>{ flip=!flip; sfx("tap"); if(flip) speak(c.k); draw() };
    document.getElementById("pv").onclick=()=>{ if(i){ i--; flip=false; draw() } };
    document.getElementById("nx").onclick=()=>{ if(i<order.length-1){ i++; flip=false; draw() } else rewardModal("카드 학습 완료!",`${SAY_NAME[cat]} ${order.length}개를 살펴봤어요. 이제 퀴즈로 확인해 볼까요?`,0,()=>sayCards(list,cat))   /* 코인 막기 (2026-10-27): 카드는 넘겨 보기만 해도 돼서 코인 없음 · 퀴즈 만점으로 받아요 */ } }
  draw() }

/* ----- 퀴즈 (풀이와 '이럴 때 써요' 설명이 함께 나와요) ----- */
function sayQuiz(list,cat,o){ o=o||{}; const N=Math.min(list.length*2,typeof QUIZ_N!=="undefined"?QUIZ_N:8), rev=!!o.review;   /* 8문제 고정 (주차 1개 = 말 4개면 8문제) */
  const src=shuffle(pickWeighted(list,N)), seenQ=new Set(); const qs=src.map(c=>{ let q; for(let t=0;t<8;t++){ q=makeSayQ(c,{types:o.types||undefined}); const key=c.h+"|"+q.tag+"|"+(q.desc||q.q); if(!seenQ.has(key)){ seenQ.add(key); break } } return q });
  let i=0, right=0, combo=0, pend=0, best=0, miss=[], busy=false; const WM=sayMul()*(rev?1.3:1);
  const SM=(()=>{ const d=day(); return d.sets>=DAILY_SETS?0:stairMul(d.sets) })(), shown=()=>Math.min(pend,coinLeft());
  function draw(){ const q=qs[i]; markSeen(q.c.h);
    $app.innerHTML = topbar(rev?"복습 퀴즈":o.fromNotes?"틀린 문제 다시":`${SAY_NAME[cat]} 퀴즈`) + `
    <div class="qtop">
      <div class="prog"><div class="pt"><span>학습 진행</span><b>${i+1} / ${N}</b></div><div class="bar"><i style="width:${i/N*100}%"></i></div></div>
      <div class="reward" id="rw"><div class="eyebrow">REWARD</div><b>${ico("coin","ci")}+<span id="pend">${shown()}</span></b><small id="cmb">${combo>=2?`${combo}연속 정답!`:"연속 정답이면 더 많이"}</small></div>
    </div>
    <div class="qwrap">
      <div class="qcard sayq"><span class="qtag"># 문제 ${i+1} · ${q.tag}</span>${q.big?`<div class="qbig sayBig">${esc(q.big)}</div>`:""}${q.desc?`<div class="sayDesc">${esc(q.desc)}</div>`:""}<div class="qq sayQ">${esc(q.q)}</div>
        <div class="sayWhy" id="why" hidden></div></div>
      <div class="qopts">
        ${q.opts.map((op,k)=>`<button class="qo ${q.long?"sayLong":"saySh"}" data-k="${k}"><span class="L">${q.two?"":"ABCD"[k]}</span><span class="T">${esc(op.text)}</span><span class="gain"></span></button>`).join("")}
        <div class="qtools"><button id="skip">모르겠어요</button><button id="nextQ" class="btn gold" hidden>다음 문제 →</button><span class="combo">STREAK ${combo}</span></div>
      </div>
    </div>`;
    bindBack();
    const btns=[...$app.querySelectorAll(".qo")];
    document.getElementById("skip").onclick=()=>{ if(!busy) answer(null) };
    btns.forEach(b=>b.onclick=()=>{ if(!busy) answer(b) });
    function answer(b){ busy=true; const ok=!!(b&&q.opts[+b.dataset.k].ok);
      btns.forEach(x=>{ x.disabled=true; if(q.opts[+x.dataset.k].ok) x.classList.add("ok") });
      P.stats.q++; trackAns(q.c,ok);
      if(ok){ right++; combo++; best=Math.max(best,combo); const g=Math.round(comboGain(combo)*WM*SM); pend+=g; b.querySelector(".gain").textContent="+"+g;
        document.getElementById("pend").textContent=shown(); document.getElementById("cmb").textContent=combo>=2?`${combo}연속 정답!`:"정답!";
        const rw=document.getElementById("rw"); rw.classList.remove("pop"); void rw.offsetWidth; rw.classList.add("pop");
        P.stats.c++; P.mastery[q.c.h]=(P.mastery[q.c.h]||0)+1; if(q.ctx) sayCtx(q.c); if(o.fromNotes) P.swrong=(P.swrong||[]).filter(h=>h!==q.c.h);
        sfx("ok"); if(combo>=3) stamp(`${combo}연속!`); speak(q.c.k) }
      else { combo=0; if(b) b.classList.add("no"); miss.push(q.c); addWrong(q.c.h); sfx("no"); document.getElementById("cmb").textContent=b?"아쉬워요!":"다음엔 맞혀요!" }
      saveP();
      const w=document.getElementById("why"); w.hidden=false; w.className="sayWhy "+(ok?"good":"bad");
      w.innerHTML=`<b>${ok?"정답! ":"정답은 "}'${esc(q.ans)}'</b>${q.c.hz?` <span class="sayHz">${esc(q.c.hz)}</span>`:""}<br>${esc(q.why)}${(q.c.sim||[]).length?`<div class="srMini">🤝 비슷한 말: <b>${q.c.sim.map(r=>esc(r.k)).join(" · ")}</b></div>`:""}`;
      const go=()=>{ if(go.d) return; go.d=1; i++; busy=false; i<N?draw():finish() };
      if(ok) setTimeout(go,1900); else { const nb=document.getElementById("nextQ"); nb.hidden=false; document.getElementById("skip").hidden=true; nb.onclick=go } } }
  function finish(){ const perfect=right===N; if(perfect) pend+=Math.round(pend*.3)+Math.round(10*WM*SM);   /* 만점 보너스: 30% + 10 */
    const before=sayDoneWeeks(); if(rev&&perfect){ P.srev=P.srev||{}; o.review.forEach(w=>P.srev[cat+w]=Date.now()) } sayStamp();
    const acc=N?right/N:0, cnt=acc>=.6, coinOk=right>=Math.max(1,N-1); if(!coinOk) pend=0;   /* 2026-10-27: 7개 이상(한 개까지 틀려도) 코인·경험치 · 만점이면 보너스 */
    if(o.fromNotes&&coinOk&&typeof day==="function"){ day().wPass=1; saveP() }   /* 오답 퀴즈 통과 → 오늘 게임 조건 (2026-10-28) */
    let nBonus=0; if(o.fromNotes&&coinOk&&pend>0&&new Set(list.map(x=>x.h)).size>=4){ nBonus=Math.round(pend*.3); pend+=nBonus }   /* 오답 퀴즈 보너스 ×1.3 (서로 다른 4개 이상) */
    let repNote=""; if(coinOk&&pend>0){ const dd=day(); dd.wq=dd.wq||{}; const key=(o.fromNotes?"n":"")+cat+(rev?"r":"")+[...(o.review||list.map(x=>x.w))].filter((v,i,A)=>A.indexOf(v)===i).sort((a,b)=>a-b).join(","), n=dd.wq[key]||0; dd.wq[key]=n+1; if(n>=3){ pend=Math.round(pend*.3); repNote="같은 주차는 하루 3번까지 코인을 다 받아요. 이제는 30%만! 다른 주차도 공부해 봐요" } }   /* 찍기 막기 (2026-10-27): 만점일 때만 코인 · 60% 이상이면 오늘 공부 세트로는 쳐요 */
    const accNote=perfect?repNote:coinOk?(repNote||`${right} / ${N} · 만점이면 보너스 코인을 더 받아요!`):acc>=.6?`${right} / ${N} · ${Math.max(1,N-1)}개 이상 맞혀야 코인을 받아요. 오늘 공부 세트에는 들어가요!`:`${right} / ${N} · 60% 이상 맞혀야 오늘 공부 세트에 들어가요. 먼저 카드로 익히고 와요!`;
    const r=grantSet(pend,true,true,cnt), after=sayDoneWeeks(), um=[...new Set(miss)];
    const newW=[]; for(let w=1;w<=SAY_WEEKS[cat];w++) if(sayWeekDone(cat,w)&&(P.srev||{})[cat+w]>Date.now()-60000&&!(rev&&o.review.includes(w))) newW.push(w);
    modal.dataset.dismiss="no";
    openModal(`<div class="eyebrow">COMPLETE</div><h3>${perfect?"만점! 학습 완료!":"학습 완료!"}</h3>
      <p>맞힌 문제 <b style="font-family:var(--f-ui);font-size:24px;color:var(--gold)">${right} / ${N}</b> · 최고 ${best}연속</p>
      ${after>before||newW.length?`<p class="sayNew">★ ${newW.length?newW.join(", ")+"주차를 다 외웠어요!":"새 주차를 외웠어요!"} (외운 주차 ${after}개 · 코인 ×${sayMul()})</p>`:""}
      ${rev&&perfect?`<p class="sayNew">★ 복습 완료! ${o.review.join(", ")}주차가 다시 반짝여요</p>`:""}
      <div class="mc">${ico("coin","ci")}+${r.got}</div>${accNote?`<p class="muted" style="color:#c8372d;font-weight:600">${accNote}</p>`:""}${r.exp?`<p class="expline">${heroById(P.hero).name} 경험치 +${r.exp}</p>`:""}
      ${r.capped||coinLeft()<=0?`<p class="muted" style="color:#c8372d">${capNote()||"오늘 코인 한도에 거의 닿았어요"}</p>`:""}
      ${um.length?`<div class="eyebrow">다시 볼 말</div><div class="misslist sayMiss">${um.map(c=>`<span><b>${esc(c.k)}</b>${esc(c.t)}</span>`).join("")}</div>`:""}
      <button class="btn gold big" id="take">${r.got?"코인 받기":"확인"}</button>
      <div class="btns" id="after" hidden><button class="btn ghost" id="again">한 번 더</button><button class="btn ghost" id="bk">학습하기로</button></div>`);
    if(perfect) setTimeout(()=>stamp("만점!"),200);
    document.getElementById("take").onclick=e=>{ e.currentTarget.hidden=true; document.getElementById("after").hidden=false; if(r.got){ sfx("coin"); countUp(P.coins-r.got,P.coins) } };
    document.getElementById("again").onclick=()=>{ modal.dataset.dismiss=""; closeModal(); sayQuiz(list,cat,o) };
    document.getElementById("bk").onclick=()=>{ modal.dataset.dismiss=""; closeModal(); learn() } }
  draw() }

/* ----- 도감: 한자 / 사자성어 / 속담 ----- */
function dexTabs(cur){ const n=c=>SAY_ALL[c].filter(sayMastered).length, nc=typeof cardCount==="function"?cardCount():0; return `<div class="ltabs">${[["H","한자"],["S","사자성어"],["P","속담"],["B","보스 카드"]].map(([k,nm])=>`<button class="ltab dtab ${cur===k?"on":""}" data-tab="${k}">${nm}${k==="S"||k==="P"?`<small>익힌 말 ${n(k)}/${SAY_ALL[k].length}</small>`:k==="B"?`<small>${nc}/120장</small>`:""}</button>`).join("")}</div>` }
function bindDexTabs(){ $app.querySelectorAll(".dtab").forEach(b=>b.onclick=()=>{ P.set.dtab=b.dataset.tab; saveP(); dex() }) }
function sayDex(cat){ const L=SAY_ALL[cat], m=L.filter(sayMastered).length, seen=L.filter(x=>(P.seen||{})[x.h]).length, nm=SAY_NAME[cat];
  $app.innerHTML = topbar("도감") + dexTabs(cat) + `
  <section class="panel"><div class="dexHead"><div class="dexBar"><div class="prog"><div class="pt"><span>익힌 ${nm} (4번 맞히고 생활 문제 3번 맞히기)</span><b>${m} / ${L.length}</b></div><div class="bar"><i style="width:${m/L.length*100}%"></i></div></div></div>
    <span class="meta">만난 ${nm} ${seen}개 · 누르면 뜻과 쓰임을 볼 수 있어요</span></div></section>
  <div class="dexgrid">${Array.from({length:SAY_WEEKS[cat]},(_,i)=>i+1).map(w=>`<div class="dweek"><h3>${w}주차${sayWeekDone(cat,w)?" ★":""}</h3><div class="drow sayrow">${L.filter(x=>x.w===w).map(x=>{ const ms=sayMastered(x), s=(P.seen||{})[x.h];
      return `<button class="dz sayz ${ms?"ms":s?"":"un"}" data-h="${esc(x.h)}"><b>${s||ms?esc(x.k):"?"}</b>${x.hz&&(s||ms)?`<small>${esc(x.hz)}</small>`:""}<i>${ms?"익힘":s?`${Math.min(SAY_MASTER,(P.mastery||{})[x.h]||0)}/${SAY_MASTER} · 생활 ${Math.min(SAY_CTX,(P.sctx||{})[x.h]||0)}/${SAY_CTX}`:"아직"}</i></button>` }).join("")}</div></div>`).join("")}</div>`;
  bindBack(); bindDexTabs();
  $app.querySelectorAll(".sayz").forEach(b=>b.onclick=()=>{ const x=sayFind(b.dataset.h); if(!(P.seen||{})[x.h]){ toast(`아직 만나지 않은 ${nm}예요. 학습하기에서 만나 보세요!`); return } sayDetail(x) }) }
function sayDetail(x){ speak(x.k);
  openModal(`<div class="eyebrow">${SAY_NAME[x.cat]} · ${x.w}주차</div><h3 style="font-size:30px;margin:4px 0">${esc(x.k)}</h3>${x.hz?`<div class="scHz">${esc(x.hz)}</div>`:""}
    <p style="font-family:var(--f-ui);font-size:18px;line-height:1.55;text-align:left">${esc(x.m)}</p>
    <div class="scTip" style="text-align:left">💡 ${esc(x.t)}</div>
    <div class="scEx" style="color:#2b2216"><b>이렇게 써요</b>${esc(x.o)}</div>
    <div class="scEx" style="color:#2b2216;margin-top:8px"><b>이런 상황에서 <span id="sdN">1</span>/${x.s.length}</b><span id="sdS">${esc(x.s[0])}</span></div>
    ${x.s.length>1?`<button class="btn ghost" id="sdNx" style="margin-top:6px;width:100%">🔄 다른 상황 보기</button>`:""}
    ${sayRelHtml(x)}
    <div class="btns"><button class="btn gold" id="sdOk">닫기</button></div>`);
  { let j=0; const nb=document.getElementById("sdNx"); if(nb) nb.onclick=()=>{ sfx("tap"); j=(j+1)%x.s.length; document.getElementById("sdS").textContent=x.s[j]; document.getElementById("sdN").textContent=j+1 } }
  bindSayRel(mcard); document.getElementById("sdOk").onclick=()=>closeModal() }
/* 오답 노트에 붙는 사자성어·속담 칸 */
function sayNotesHtml(){ const L=(P.swrong||[]).map(sayFind).filter(Boolean); if(!L.length) return "";
  return `<section class="panel" style="margin-top:14px"><div class="row"><h2>틀린 사자성어·속담</h2><span class="meta">${L.length}개 · 다시 풀어서 맞히면 빠져요</span></div>
    <div class="notelist sayNotes">${L.map(x=>`<button class="note saynote" data-h="${esc(x.h)}"><b style="font-size:20px">${esc(x.k)}</b><span>${esc(x.t)}</span><small>${SAY_NAME[x.cat]} ${x.w}주차 · 눌러서 보기</small></button>`).join("")}</div>
    <div class="btns">${["S","P"].filter(c=>L.some(x=>x.cat===c)).map(c=>`<button class="btn gold sayretry" data-c="${c}">틀린 ${SAY_NAME[c]} 다시 풀기</button>`).join("")}</div></section>` }
function bindSayNotes(){ $app.querySelectorAll(".saynote").forEach(b=>b.onclick=()=>sayDetail(sayFind(b.dataset.h)));
  $app.querySelectorAll(".sayretry").forEach(b=>b.onclick=()=>{ const c=b.dataset.c; sayQuiz((P.swrong||[]).map(sayFind).filter(x=>x&&x.cat===c),c,{fromNotes:true}) }) }

